window.POEM_DB=window.POEM_DB||{};POEM_DB["tang_011"]={"n":"姚合","dyn":"唐","poems":[{"t":"乞新茶","f":"七言绝句","c":["嫩绿微黄碧涧春，采时闻道断荤辛。","不将钱买将诗乞，借问山翁有几人。"]},{"t":"古碑","f":"五言绝句","c":["荒田一片石，文字满青苔。","不是逢闲客，何人肯读来。"]},{"t":"对月","f":"七言绝句","c":["银轮玉兔向东流，瑩净三更正好游。","一片黑云何处起，皂罗笼却水精毬。"]},{"t":"老马","f":"五言绝句","c":["卧来扶不起，唯向主人嘶。","惆怅东郊道，秋来雨作泥。"]},{"t":"访僧法通不遇","f":"五言绝句","c":["访师师不遇，礼佛佛无言。","依旧将烦恼，黄昏入宅门。"]},{"t":"过友人山庄","f":"七言绝句","c":["蕙带缠腰复野蔬，一庄水竹数房书。","举头忽见南山雪，便说休官相近居。"]},{"t":"佛舍见胡子有嘲","f":"五言绝句","c":["明明复夜夜，胡子即成翁。","唯是真知性，不来生灭中。"]},{"t":"别杭州","f":"五言绝句","c":["醉与江涛别，江涛惜我游。","他年婚嫁了，终老此江头。"]},{"t":"别胡逸","f":"七言绝句","c":["记得春闱同席试，逡巡何啻十年馀。","今日相逢又相送，予乘五马子单车。"]},{"t":"听僧云端讲经","f":"七言绝句","c":["无生深旨诚难解，唯是师言得正真。","远近迟斋来谛听，酒坊鱼市尽无人。"]},{"t":"杏园","f":"七言绝句","c":["江头数顷杏花开，车马争先尽此来。","欲待无人连夜看，黄昏树树满尘埃。"]},{"t":"杏园宴上谢座主","f":"七言绝句","c":["得陪桃李植芳丛，别感生成太昊功。","今日无言春雨后，似含冷涕谢东风。"]},{"t":"杨柳枝词五首 其一","f":"七言绝句","c":["黄金丝挂粉墙头，动似颠狂静似愁。","游客见时心自醉，无因得见谢家楼。"]},{"t":"杨柳枝词五首 其二","f":"七言绝句","c":["叶叶如眉翠色浓，黄莺偏恋语从容。","桥边陌上无人识，雨湿烟和思万重。"]},{"t":"杨柳枝词五首 其三","f":"七言绝句","c":["江上东西离别饶，旧条折尽折新条。","亦知春色人将去，犹胜狂风取次飘。"]},{"t":"杨柳枝词五首 其四","f":"七言绝句","c":["二月杨花触处飞，悠悠漠漠自东西。","谢家咏雪徒相比，吹落庭前便作泥。"]},{"t":"杨柳枝词五首 其五","f":"七言绝句","c":["江亭杨柳折还垂，月照深黄几树丝。","见说隋堤枯已尽，年年行客怪春迟。"]},{"t":"穷边词二首 其一","f":"七言绝句","c":["将军作镇古汧洲，水腻山春节气柔。","清夜满城丝管散，行人不信是边头。"]},{"t":"穷边词二首 其二","f":"七言绝句","c":["箭利弓调四镇兵，蕃人不敢近东行。","沿边千里浑无事，唯见平安火入城。"]},{"t":"和王郎中题华州李中丞厅","f":"七言绝句","c":["莲华峰下郡斋前，绕砌穿池贮瀑泉。","君到亦应闲不得，主人草圣复诗仙。"]},{"t":"和李十二舍人冬至日","f":"五言绝句","c":["献寿人皆庆，南山复北堂。","从今千万日，此日又初长。"]},{"t":"和李十二舍人直日放朝对雪","f":"七言绝句","c":["今朝街鼓何人听，朝客开门对雪眠。","岂比直庐丹禁里，九重天近色弥鲜。"]},{"t":"和前吏部韩侍郎夜泛南溪","f":"七言绝句","c":["辞得官来疾渐平，世间难有此高情。","新秋月满南溪里，引客乘船处处行。"]},{"t":"咏盆池","f":"七言绝句","c":["浮萍重叠水团圆，客绕千遭屐齿痕。","莫惊池里寻常满，一井清泉是上源。"]},{"t":"咏新菊","f":"五言绝句","c":["黄金色未足，摘取且尝新。","若待重阳日，何曾异众人。"]},{"t":"夜期友生不至","f":"七言绝句","c":["忍寒停酒待君来，酒作凌凘火作灰。","半夜出门重立望，月明先自下高台。"]},{"t":"牧杭州谢李太尉德裕","f":"七言绝句","c":["皇恩特许拜杭坛，欲谢旌旄去就难。","偷拟白头瞻画戟，四神俱散发毛寒。"]},{"t":"采松花","f":"七言绝句","c":["拟服松花无处学，嵩阳道士忽相教。","今朝试上高枝采，不觉倾翻仙鹤巢。"]},{"t":"春日游慈恩寺","f":"五言绝句","c":["年长归何处，青山未有家。","赏春无酒饮，多看寺中花。"]},{"t":"秋中夜坐","f":"五言绝句","c":["疏散永无事，不眠常夜分。","月中松露滴，风引鹤同闻。"]},{"t":"送张齐物主簿赴内乡","f":"七言绝句","c":["几年山下事仙翁，名在长生箓籍中。","烧得药成须寄我，曾为主簿与君同。"]},{"t":"送贾岛及钟浑","f":"七言绝句","c":["日日攻诗亦自彊，年年供应在名场。","春风驿路归何处，紫阁山边是草堂。"]},{"t":"送僧 其一","f":"七言绝句","c":["人间扰扰唯闲事，自见高人只有诗。","寂寞嵩峰云外寺，常多梦里过斋时。"]},{"t":"送僧 其二","f":"七言绝句","c":["城中听得新经论，却过关东说向人。","旧国门徒终日望，见时应是见真身。"]},{"t":"送薛二十三郎中赴婺州","f":"五言绝句","c":["我住浙江西，君去浙江东。","日日心来往，不畏浙江风。"]},{"t":"闻新蝉寄李馀","f":"七言绝句","c":["往年六月蝉应到，每到闻时骨欲惊。","今日槐花还似发，却愁听尽更无声。"]},{"t":"寄王玄伯","f":"七言绝句","c":["夜归晓出满衣尘，转觉才名带累身。","莫觅旧来终日醉，世间杯酒属闲人。"]},{"t":"寄右史李定言","f":"七言绝句","c":["才归龙尾含鸡舌，更立螭头运兔毫。","阊阖欲开金漏尽，冕旒初坐御香高。"]},{"t":"寄李干","f":"七言绝句","c":["寻常自怪诗无味，虽被人吟不喜闻。","见说与君同一格，数篇到火却休焚。"]},{"t":"寄灵一律师","f":"七言绝句","c":["梵书钞律千馀纸，净院焚香独受持。","童子病来烟火绝，清泉漱口过斋时。"]},{"t":"寄酬卢侍御","f":"七言绝句","c":["诗新得意恣狂疏，挥手终朝力有馀。","今到诗家浑手战，欲题名字倩人书。"]},{"t":"寄裴起居","f":"七言绝句","c":["千官晓立炉烟里，立近丹墀是起居。","彩笔专书皇帝语，书成几卷太平书。"]},{"t":"崔少卿鹤","f":"七言绝句","c":["入门石径半高低，闲处无非是药畦。","致得仙禽无去意，花间舞罢洞中栖。"]},{"t":"晦日送穷三首 其一","f":"五言绝句","c":["年年到此日，沥酒拜街中。","万户千门看，无人不送穷。"]},{"t":"晦日送穷三首 其二","f":"五言绝句","c":["送穷穷不去，相泥欲何为。","今日官家宅，淹留又几时。"]},{"t":"晦日送穷三首 其三","f":"五言绝句","c":["古人皆恨别，此别恨消魂。","只是空相送，年年不出门。"]},{"t":"晦日宴刘值录事宅","f":"七言绝句","c":["花落莺飞深院静，满堂宾客尽诗人。","城中杯酒家家有，唯是君家酒送春。"]},{"t":"游天台上方","f":"七言绝句","c":["晓上上方高处立，路人羡我此时身。","白云向我头上过，我更羡他云路人。"]},{"t":"谢韬光上人","f":"七言绝句","c":["上方清净无因住，唯愿他生得住持。","只恐无生复无我，不知何处更逢师。"]},{"t":"谢韬光上人赠百龄藤杖","f":"七言绝句","c":["衰病近来行少力，光公乞我百龄藤。","闲来杖此向何处，过水缘山只访僧。"]},{"t":"辞白宾客归后寄","f":"七言绝句","c":["千骑红旗不可攀，水头独立暮方还。","家人怪我浑如病，尊酒休倾笔砚间。"]},{"t":"酬令狐郎中见寄","f":"七言绝句","c":["昨是儿童今是翁，人间日月急如风。","常闻欲向沧江去，除我无人与子同。"]},{"t":"裴大夫见过","f":"七言绝句","c":["湖南谯国尽英髦，心事相期节义高。","解下佩刀无所惜，新闻天子付三刀。"]},{"t":"题鹤雏","f":"五言绝句","c":["羽毛生未齐，嶛峭丑于鸡。","夜夜穿笼出，捣衣砧上栖。"]},{"t":"赠丘郎中","f":"七言绝句","c":["绕篱栽杏种黄精，晓侍垆烟暮出城。","万事将身求总易，学君难得是长生。"]},{"t":"九日忆砚山旧居","f":"五言律诗","c":["帝里闲人少，谁同把酒杯。","砚山篱下菊，今日几枝开。","晓角惊眠起，秋风引病来。","长年归思切，更值雁声催。"]},{"t":"九日寄钱可复","f":"五言律诗","c":["数杯黄菊酒，千里白云天。","上国名方振，戎州病未痊。","静愁惟忆醉，闲走不胜眠。","惆怅东门别，相逢知几年。"]},{"t":"八月十五夜看月","f":"五言律诗","c":["亭亭千万里，三五复秋中。","此夕光应绝，常时思不同。","九霄微有露，四海静无风。","惆怅逡巡别，谁能看碧空。"]},{"t":"万年县中雨夜会宿寄皇甫甸","f":"五言律诗","c":["县斋还寂寞，夕雨洗苍苔。","清气灯微润，寒声竹共来。","虫移上阶近，客起到门回。","想得吟诗处，唯应对酒杯。"]},{"t":"下第","f":"五言律诗","c":["枉为乡里举，射鹄艺浑疏。","归路羞人问，春城赁舍居。","闭门辞杂客，开箧读生书。","以此投知己，还因胜自馀。"]},{"t":"乞酒","f":"五言律诗","c":["闻君有美酒，与我正相宜。","溢瓮清如水，黏杯半似脂。","岂唯消旧病，且要引新诗。","况此便便腹，无非是满卮。"]},{"t":"山中述怀","f":"五言律诗","c":["为客久未归，寒山独掩扉。","晓来山鸟散，雨过杏花稀。","天远云空积，溪深水自微。","此情对春色，尽醉欲忘机。"]},{"t":"山中寄友人","f":"五言律诗","c":["路岐何渺邈，在客易蹉跎。","却是去家远，因循住日多。","几看春草绿，又见塞鸿过。","未有进身处，忍教抛薜萝。"]},{"t":"山居寄友人","f":"五言律诗","c":["独在山阿里，朝朝遂性情。","晓泉和雨落，秋草上阶生。","因客始沽酒，借书方到城。","诗情聊自遣，不是趁声名。"]},{"t":"从军乐二首 其一","f":"五言律诗","c":["每日寻兵籍，经年别酒徒。","眼疼长不校，肺病且还无。","僮仆惊衣窄，亲情觉语粗。","几时得归去，依旧作山夫。"]},{"t":"从军乐二首 其二","f":"五言律诗","c":["朝朝十指痛，唯署点兵符。","贫贱依前在，颠狂一半无。","身惭山友弃，胆赖酒杯扶。","谁道从军乐，年来镊白须。"]},{"t":"天竺寺殿前立石","f":"七言律诗","c":["补天残片女娲抛，扑落禅门压地坳。","霹雳划深龙旧攫，屈槃痕浅虎新抓。","苔黏月眼风挑剔，尘结云头雨磕敲。","秋至莫言长矻立，春来自有薜萝交。"]},{"t":"忆山","f":"五言律诗","c":["闲处无人到，乖疏称野情。","日高搔首起，林下散衣行。","泉引窗前过，云看石罅生。","别来愁欲老，虚负出山名。"]},{"t":"文宗皇帝挽词三首 其一","f":"五言律诗","c":["垂拱开成化，愔愔雅乐全。","千官方就日，四海忽无天。","尧舜非传子，殷周但卜年。","圣功青史外，刊石在陵前。"]},{"t":"文宗皇帝挽词三首 其二","f":"五言律诗","c":["代以无为理，车书万国同。","继兄还付弟，授圣悉推公。","云雾疑无日，笳箫别起风。","金茎难复见，寒露落空中。"]},{"t":"文宗皇帝挽词三首 其三","f":"五言律诗","c":["龙归攀不得，髯在侍臣边。","彻奠新阡起，登山吉从全。","关河佳气散，夷夏哭声连。","寂寞玄宫闭，朝昏千万年。"]},{"t":"冬夜书事寄两省阁老","f":"七言律诗","c":["天寒渐觉雁声疏，新月微微玉漏初。","海峤只宜今日去，故乡已过十年馀。","发稀岂易胜玄冕，眼暗应难写谏书。","阁下群公尽高思，谁能携酒访贫居。"]},{"t":"会将作崔监东园","f":"五言律诗","c":["墙北走红尘，墙东接白云。","山光衣上见，药气酒中闻。","此会诚堪惜，穷秋日又曛。","人间唯有醉，醉后复何云。"]},{"t":"军城夜会","f":"五言律诗","c":["军城夜禁乐，饮酒每题诗。","坐稳吟难尽，寒多醉较迟。","远钟惊漏压，微月被灯欺。","此会诚堪惜，天明是别离。"]},{"t":"同卫尉崔少卿九月六日饮","f":"五言律诗","c":["酒熟菊还芳，花飘盏亦香。","与君先一醉，举世待重阳。","风色初晴利，虫声向晚长。","此时如不饮，心事亦应伤。"]},{"t":"同诸公会太府韩卿宅","f":"七言律诗","c":["九寺名卿才思雄，邀欢笔下与杯中。","六街鼓绝尘埃息，四座筵开语笑同。","燄燄兰缸明狭室，丁丁玉漏发深宫。","即听鸡唱天门晓，吏事相牵西复东。"]},{"t":"同裴起居厉侍御放朝游曲江","f":"五言律诗","c":["暑月放朝频，青槐路绝尘。","雨晴江色出，风动草香新。","独立分幽岛，同行得静人。","此欢宜稍滞，此去与谁亲。"]},{"t":"寻僧不遇","f":"五言律诗","c":["入门愁自散，不假见僧翁。","花落煎茶水，松生醒酒风。","拂床寻古画，拔刺看新丛。","别有游人见，多疑住此中。"]},{"t":"庄恪太子挽词二首 其一","f":"五言律诗","c":["晓漏启严城，宫臣缟素行。","灵仪先卤簿，新谥在铭旌。","云晦郊原色，风连霰雪声。","凄凉望苑路，春草即应生。"]},{"t":"庄恪太子挽词二首 其二","f":"五言律诗","c":["寒日青宫闭，玄堂渭水滨。","华夷笺乍绝，凶吉礼空新。","薤露歌连哭，泉扉夜作晨。","吹笙今一去，千古在逡巡。"]},{"t":"成名后留别从兄","f":"七言律诗","c":["一辞山舍废躬耕，无事悠悠住帝城。","为客衣裳多不稳，和人诗句固难精。","几年秋赋唯知病，昨日春闱偶有名。","却出关东悲复喜，归寻弟妹别仁兄。"]},{"t":"扬州春词三首 其一","f":"五言律诗","c":["广陵寒食天，无雾复无烟。","煖日凝花柳，春风散管弦。","园林多是宅，车马少于船。","莫唤游人住，游人困不眠。"]},{"t":"扬州春词三首 其二","f":"五言律诗","c":["满郭是春光，街衢土亦香。","竹风轻履舄，花露腻衣裳。","谷鸟鸣还艳，山夫到更狂。","可怜游赏地，炀帝国倾亡。"]},{"t":"扬州春词三首 其三","f":"五言律诗","c":["江北烟光里，淮南胜事多。","市廛持烛入，邻里漾船过。","有地惟栽竹，无家不养鹅。","春风荡城郭，满耳是笙歌。"]},{"t":"早春山居寄城中知己","f":"七言律诗","c":["阳和潜发荡寒阴，便使川原景象深。","入户风泉声沥沥，当轩云岫影沈沈。","残云带雨轻飘雪，嫩柳含烟小绽金。","虽有眼前诗酒兴，邀游争得称闲心。"]},{"t":"早春闲居","f":"五言律诗","c":["寂寞日何为，闲居春色迟。","惊风起庭雪，寒雨长檐澌。","强饮樽中酒，嘲山世外诗。","此生仍且在，难与老相离。"]},{"t":"早夏郡楼宴集","f":"五言律诗","c":["官散有闲情，登楼步稍轻。","窗云带雨气，林鸟杂人声。","晓日襟前度，微风酒上生。","城中会难得，扫壁各书名。"]},{"t":"舟行书事寄杭州崔员外","f":"五言律诗","c":["张颐任酒浇，开眼信花烧。","旧国归何滞，新知别又遥。","夜行篙触石，晚泊缆依桥。","若未重相见，无门解寂寥。"]},{"t":"过不疑上人院","f":"五言律诗","c":["九经通大义，内典自应精。","帘冷连松影，苔深减覆声。","相逢幸此日，相失恐来生。","觉路何门去，师须引我行。"]},{"t":"过天津桥晴望","f":"五言律诗","c":["闲立津桥上，寒光动远林。","皇宫对嵩顶，清洛贯城心。","雪路初晴出，人家向晚深。","自从王在镐，天宝至如今。"]},{"t":"过无可上人院","f":"五言律诗","c":["寥寥听不尽，孤磬与疏钟。","烦恼师长别，清凉我暂逢。","蚁行经古藓，鹤毳落深松。","自想归时路，尘埃复几重。"]},{"t":"过无可僧院","f":"五言律诗","c":["忆师眠复起，永夜思迢迢。","月下门方掩，林中寺更遥。","钟声空下界，池色在清宵。","终拟修禅观，窗间卷欲烧。"]},{"t":"过李处士山居","f":"五言律诗","c":["闲居昼掩扉，门柳荫蔬畦。","因病方收药，寻僧始度溪。","少逢人到户，时有燕衔泥。","萧洒身无事，名高孰与齐。"]},{"t":"过杜氏江亭","f":"五言律诗","c":["上国千馀里，逢春且胜游。","暂闻新鸟戏，似解旅人愁。","野色吞山尽，江烟衬水流。","村醪须一醉，无恨滞行舟。"]},{"t":"过杨处士幽居","f":"五言律诗","c":["引水穿风竹，幽声胜远溪。","裁衣延野客，剪翅养山鸡。","酒熟听琴酌，诗成削树题。","惟愁春气暖，松下雪和泥。"]},{"t":"过灵泉寺","f":"五言律诗","c":["偶寻灵迹去，幽径入氲氛。","转壑惊飞鸟，穿山踏乱云。","水从岩下落，溪向寺前分。","释子游何处，空堂日渐曛。"]},{"t":"过昙花宝上人院","f":"五言律诗","c":["九陌最幽寺，吾师院复深。","烟霜同覆屋，松竹杂成林。","鸟语境弥寂，客来机自沈。","早知能到此，应不戴朝簪。"]},{"t":"过城南僧院","f":"五言律诗","c":["寺对远山起，幽居仍是师。","斜阳通暗隙，残雪落疏篱。","松静鹤栖定，廊虚钟尽迟。","朝朝趋府吏，来此是相宜。"]},{"t":"过钦上人院","f":"五言律诗","c":["有相无相身，唯师说始真。","修篁半庭影，清磬几僧邻。","古壁丹青落，虚檐鸟雀驯。","伊余求了义，羸马往来频。"]},{"t":"过稠上人院","f":"五言律诗","c":["清羸一饭师，闲院亦披衣。","应诏常翻译，修心出是非。","雪中疏磬度，林际晚风归。","蔬食常来此，人间护净稀。"]},{"t":"别李馀","f":"五言律诗","c":["病童随瘦马，难算往来程。","野寺僧相送，河桥酒滞行。","足愁无道性，久客会人情。","何计羁穷尽，同居不出城。"]},{"t":"别春","f":"七言律诗","c":["留春不得被春欺，春若无情遣泥谁。","寂寞自疑生冷病，凄凉还似别亲知。","随风未辨归何处，浇酒唯求住少时。","一去近当三百日，从朝至夜是相思。"]},{"t":"别贾岛","f":"五言律诗","c":["懒作住山人，贫家日赁身。","书多笔渐重，睡少枕长新。","野客狂无过，诗仙瘦始真。","秋风千里去，谁与我相亲。"]},{"t":"县中秋宿","f":"五言律诗","c":["鼓绝门方掩，萧条作吏心。","露垂庭际草，萤照竹间禽。","棋罢嫌无月，眠迟听尽砧。","还知未离此，时复更相寻。"]},{"t":"杨给事师皋哭亡爱姬英英窃闻诗人多赋因而继和","f":"七言律诗","c":["真珠为土玉为尘，未识遥闻鼻亦辛。","天上还应收至宝，世间难得是佳人。","朱丝自断虚银烛，红粉潜销冷绣裀。","见说忘情唯有酒，夕阳对酒更伤神。"]},{"t":"迎春","f":"七言律诗","c":["半年留醉待花开，晓去迎春夜始回。","风煖慢行寻曲水，天晴远望立高台。","亦知无处将诗请，唯得终朝把酒催。","今日柳条全弄色，游人相伴看春来。"]},{"t":"闲居","f":"五言律诗","c":["日日门长闭，邻家亦懒过。","头风春饮苦，眼晕夜书多。","幽鸟偏栖竹，凡人笑种莎。","近来难得酒，无计奈愁何。"]},{"t":"闲居","f":"五言律诗","c":["不自识疏鄙，终年住在城。","过门无马迹，满宅是蝉声。","带病吟虽苦，休官梦已清。","何当学禅观，依止古先生。"]},{"t":"闲居晚夏","f":"五言律诗","c":["闲居无事扰，旧病亦多痊。","选字诗中老，看山屋外眠。","片霞侵落日，繁叶咽鸣蝉。","对此心还乐，谁知乏酒钱。"]},{"t":"闲居遣兴","f":"五言律诗","c":["终年城里住，门户似山林。","客怪身名晚，妻嫌酒病深。","写方多识药，失谱废弹琴。","文字非经济，空虚用破心。"]},{"t":"闲居遣怀十首 其一","f":"五言律诗","c":["身外无徭役，开门百事闲。","倚松听唳鹤，策杖望秋山。","萍任连池绿，苔从匝地斑。","料无车马客，何必扫柴关。"]},{"t":"闲居遣怀十首 其二","f":"五言律诗","c":["闲卧销长日，亲朋笑我疏。","诗篇随分有，人事度年无。","情性僻难改，愁怀酒为除。","谁能思此计，空备满床书。"]},{"t":"闲居遣怀十首 其三","f":"五言律诗","c":["白日逍遥过，看山复绕池。","展书寻古事，翻卷改新诗。","赊酒风前酌，留僧竹里棋。","同人笑相问，羡我足闲时。"]},{"t":"闲居遣怀十首 其四","f":"五言律诗","c":["好景时牵目，茅斋兴有馀。","远山经雨后，庭树得秋初。","道侣怜栽药，高人笑养鱼。","优游随本性，甘被弃慵疏。"]},{"t":"闲居遣怀十首 其五","f":"五言律诗","c":["永日厨烟绝，何曾暂废吟。","闲时随思缉，小酒恣情斟。","看月嫌松密，垂纶爱水深。","世间多少事，无事可关心。"]},{"t":"闲居遣怀十首 其六","f":"五言律诗","c":["一生能几日，愁恨也无端。","遇酒酕醄饮，逢花烂熳看。","青云非失路，白发未相干。","以此多携解，将心但自宽。"]},{"t":"闲居遣怀十首 其七","f":"五言律诗","c":["万事徒纷扰，难关枕上身。","朗吟销白日，沈醉度青春。","演步怜山近，闲眠厌客频。","市朝曾不到，长免满衣尘。"]},{"t":"闲居遣怀十首 其八","f":"五言律诗","c":["野性多疏惰，幽栖更称情。","独行看影笑，闲坐弄琴声。","懒拜腰肢硬，慵趋礼乐生。","业文随日遣，不是为求名。"]},{"t":"闲居遣怀十首 其九","f":"五言律诗","c":["生计甘寥落，高名愧自由。","惯无身外事，不信世间愁。","好酒盈杯酌，闲诗任笔酬。","凉风从入户，云水更宜秋。"]},{"t":"闲居遣怀十首 其十","f":"五言律诗","c":["拙直难和洽，从人笑掩关。","不能行户外，宁解走尘间。","被酒长酣思，无愁可上颜。","何言归去事，著处是青山。"]},{"t":"和元八郎中秋居","f":"五言律诗","c":["圣代无为化，郎中似散仙。","晚眠随客醉，夜坐学僧禅。","酒用林花酿，茶将野水煎。","人生知此味，独恨少因缘。"]},{"t":"和友人新居园上","f":"五言律诗","c":["新居多野思，不似在京城。","墙上云相压，庭前竹乱生。","寻师望药力，依谱上琴声。","好是中秋夜，无尘有月明。"]},{"t":"和户部侍郎省中晚归","f":"五言律诗","c":["寒日南宫晚，闲吟半醉归。","位高行路静，诗好和人稀。","古树苔文匝，遥峰雪色微。","宁知逢彩笔，寂寞有光辉。"]},{"t":"和东都令狐留守相公","f":"七言律诗","c":["除官东守洛阳宫，恩比藩方任更雄。","拜表出时传七刻，排班衙日有三公。","旌旗严重临关外，庭宇清深接禁中。","三十六峰诗酒思，朝朝闲望与谁同。"]},{"t":"和令狐六员外直夜即事寄上相公","f":"七言律诗","c":["霜台同处轩窗接，粉署先登语笑疏。","皓月满帘听玉漏，紫泥盈手发天书。","吟诗清美招闲客，对酒逍遥卧直庐。","荣贵人间难有比，相公离此十年馀。"]},{"t":"和卢给事酬裴员外","f":"七言律诗","c":["南山雪色彻皇州，钟鼓声交晓气浮。","鸳鹭簪裾上龙尾，蓬莱宫殿压鳌头。","夕郎夜直吟仙掖，天乐和声下禁楼。","赠荅诗成才思敌，病夫欲和几朝愁。"]},{"t":"和厉玄侍御无可上人会宿见寄","f":"五言律诗","c":["九衢难会宿，况复是寒天。","朝客清贫老，林僧默悟禅。","眠迟消漏水，吟苦堕寒涎。","异日来寻我，沧江有钓船。"]},{"t":"和厉玄侍御题户部李相公庐山西林草堂","f":"五言律诗","c":["茅屋临江起，登庸复应期。","遥知归去日，自致太平时。","幽药禅僧护，高窗宿鸟窥。","行人尽歌咏，唯子独能诗。"]},{"t":"和刘禹锡主客冬初拜表怀上都故人","f":"七言律诗","c":["九陌喧喧骑吏催，百官拜表禁城开。","林疏晓日明红叶，尘静寒霜覆绿苔。","玉佩声微班始定，金函光动按初来。","此时共想朝天客，谢食方从阁里回。"]},{"t":"和李绅助教不赴看花","f":"七言律诗","c":["笑辞聘礼深坊住，门馆长闲似退居。","太学官资清品秩，高人公事说经书。","年华未是登朝晚，春色何因向酒疏。","且看牡丹吟丽句，不知此外复何如。"]},{"t":"和秘书崔少监春日游青龙寺僧院","f":"七言律诗","c":["官清书府足闲时，晓起攀花折柳枝。","九陌城中寻不尽，千峰寺里看相宜。","高人酒味多和药，自古风光只属诗。","见说往来多静者，未知前日更逢谁。"]},{"t":"和高谏议蒙兼宾客时入翰苑","f":"七言律诗","c":["兼秩恩归第一流，时寻仙路向瀛洲。","钟声迢递银河晓，林色葱笼玉露秋。","紫殿讲筵邻御座，青宫宾榻入龙楼。","从来共结归山侣，今日多应独自休。"]},{"t":"和膳部李郎中秋夕","f":"五言律诗","c":["淅淅复修修，凉风似水流。","此生难免老，举世大同愁。","萤影明苔藓，鸿声傍斗牛。","犹分省署直，何日是归休。"]},{"t":"咏云","f":"七言律诗","c":["霭霭纷纷不可穷，戛笙歌处尽随龙。","来依银汉一千里，归傍巫山十二峰。","呈瑞每闻开丽色，避风仍见挂乔松。","怜君翠染双蝉鬓，镜里朝朝近玉容。"]},{"t":"咏南池嘉莲","f":"七言律诗","c":["芙蓉池里叶田田，一本双花出碧泉。","浓淡共妍香各散，东西分艳蒂相连。","自知政术无他异，纵是祯祥亦偶然。","四野人闻皆尽喜，争来入郭看嘉莲。"]},{"t":"咏贵游","f":"七言律诗","c":["贵游多爱向深春，到处香凝数里尘。","红杏花开连锦障，绿杨阴合拂朱轮。","凤凰尊畔飞金盏，丝竹声中醉玉人。","日暮垂鞭共归去，西园宾客附龙鳞。"]},{"t":"咏莺","f":"七言律诗","c":["春来深谷雪方消，莺别寒林傍翠条。","到处为怜烟景好，隔帘多爱语声娇。","不同蜀魄啼残月，唯逐天鸡啭诘朝。","少妇听时思旧曲，玉楼从此动云韶。"]},{"t":"咏雪","f":"七言律诗","c":["愁云残腊下阳台，混却乾坤六出开。","与月交光呈瑞色，共花争艳傍寒梅。","飞随郢客歌声远，散逐宫娥舞袖回。","其那知音不相见，剡溪乘兴为君来。"]},{"t":"咏镜","f":"七言律诗","c":["铸为明镜绝尘埃，翡翠窗前挂玉台。","绣带共寻龙口出，菱花争向匣中开。","孤光常见鸾踪在，分处还因鹊影回。","好是照身宜谢女，嫦娥飞向玉宫来。"]},{"t":"夜宴太仆田卿宅","f":"五言律诗","c":["故人九寺长，邀我此同欢。","永夜开筵静，中年饮酒难。","微风侵烛影，叠漏过林端。","腊后分朝日，天明几刻残。"]},{"t":"奉和前司封苏郎中喜严常侍萧给事见访惊斑鬓之什","f":"七言律诗","c":["绕鬓沧浪有几茎，珥貂相问夕郎惊。","祗应为酒微微变，不是因年渐渐生。","东观诗成号良史，中台官罢揖高名。","即提彩笔裁天诏，谁得吟诗自在行。"]},{"t":"杭州官舍即事","f":"五言律诗","c":["临江府署清，闲卧复闲行。","苔藓疏尘色，梧桐出雨声。","渐除身外事，暗作道家名。","更喜仙山近，庭前药自生。"]},{"t":"杭州官舍偶书","f":"七言律诗","c":["钱塘刺史谩题诗，贫褊无恩懦少威。","春尽酒杯花影在，潮回画槛水声微。","闲吟山际邀僧上，暮入林中看鹤归。","无术理人人自理，朝朝渐觉簿书稀。"]},{"t":"杭州郡斋南亭","f":"五言律诗","c":["符印悬腰下，东山不得归。","独行南北近，渐老往还稀。","迸笋侵窗长，惊蝉出树飞。","田田池上叶，长是使君衣。"]},{"t":"武功县中作三十首 其一","f":"五言律诗","c":["县去帝城远，为官与隐齐。","马随山鹿放，鸡杂野禽栖。","绕舍惟藤架，侵阶是药畦。","更师嵇叔夜，不拟作书题。"]},{"t":"武功县中作三十首 其二","f":"五言律诗","c":["方拙天然性，为官是事疏。","惟寻向山路，不寄入城书。","因病多收药，缘餐学钓鱼。","养身成好事，此外更空虚。"]},{"t":"武功县中作三十首 其三","f":"五言律诗","c":["微官如马足，祗是在泥尘。","到处贫随我，终年老趁人。","簿书销眼力，杯酒耗心神。","早作归休计，深居养此身。"]},{"t":"武功县中作三十首 其四","f":"五言律诗","c":["簿书多不会，薄俸亦难销。","醉卧慵开眼，闲行懒系腰。","移花兼蝶至，买石得云饶。","且自心中乐，从他笑寂寥。"]},{"t":"武功县中作三十首 其五","f":"五言律诗","c":["晓钟惊睡觉，事事便相关。","小市柴薪贵，贫家砧杵闲。","读书多旋忘，赊酒数空还。","长羡刘伶辈，高眠出世间。"]},{"t":"武功县中作三十首 其六","f":"五言律诗","c":["性疏常爱卧，亲故笑悠悠。","纵出多携枕，因衙始裹头。","上山方觉老，过寺暂忘愁。","三考千馀日，低腰不拟休。"]},{"t":"武功县中作三十首 其七","f":"五言律诗","c":["客至皆相笑，诗书满卧床。","爱闲求病假，因醉弃官方。","鬓发寒唯短，衣衫瘦渐长。","自嫌多检束，不似旧来狂。"]},{"t":"武功县中作三十首 其八","f":"五言律诗","c":["一日看除目，终年损道心。","山宜冲雪上，诗好带风吟。","野客嫌知印，家人笑买琴。","只应随分过，已是错弥深。"]},{"t":"武功县中作三十首 其九","f":"五言律诗","c":["邻里皆相爱，门开数见过。","秋凉送客远，夜静咏诗多。","就架题书目，寻栏记药窠。","到官无别事，种得满庭莎。"]},{"t":"武功县中作三十首 其十","f":"五言律诗","c":["穷达天应与，人间事莫论。","微官长似客，远县岂胜村。","竟日多无食，连宵不闭门。","斋心调笔砚，唯写五千言。"]},{"t":"武功县中作三十首 其十一","f":"五言律诗","c":["县僻仍牢落，游人到便回。","路当边地去，村入郭门来。","酒户愁偏长，诗情病不开。","可曾衙小吏，恐谓踏青苔。"]},{"t":"武功县中作三十首 其十二","f":"五言律诗","c":["自下青山路，三年著绿衣。","官卑食肉僭，才短事人非。","野客教长醉，高僧劝早归。","不知何计是，免与本心违。"]},{"t":"武功县中作三十首 其十三","f":"五言律诗","c":["日出方能起，庭前看种莎。","吏来山鸟散，酒熟野人过。","岐路荒城少，烟霞远岫多。","同官数相引，下马上西坡。"]},{"t":"武功县中作三十首 其十四","f":"五言律诗","c":["作吏荒城里，穷愁欲不胜。","病多唯识药，年老渐亲僧。","梦觉空堂月，诗成满砚冰。","故人多得路，寂寞不相称。"]},{"t":"武功县中作三十首 其十五","f":"五言律诗","c":["谁念东山客，栖栖守印床。","何年得事尽，终日逐人忙。","醉卧谁知叫，闲书不著行。","人间长检束，与此岂相当。"]},{"t":"武功县中作三十首 其十六","f":"五言律诗","c":["朝朝眉不展，多病怕逢迎。","引水远通涧，垒山高过城。","秋灯照树色，寒雨落池声。","好是吟诗夜，披衣坐到明。"]},{"t":"武功县中作三十首 其十七","f":"五言律诗","c":["簿籍谁能问，风寒趁早眠。","每旬常乞假，隔月探支钱。","还往嫌诗僻，亲情怪酒颠。","谋身须上计，终久是归田。"]},{"t":"武功县中作三十首 其十八","f":"五言律诗","c":["闭门风雨里，落叶与阶齐。","野客嫌杯小，山翁喜枕低。","听琴知道性，寻药得诗题。","谁更能骑马，闲行祗杖藜。"]},{"t":"武功县中作三十首 其十九","f":"五言律诗","c":["腥膻都不食，稍稍觉神清。","夜犬因风吠，邻鸡带雨鸣。","守官常卧病，学道别称名。","小有洞中路，谁能引我行。"]},{"t":"武功县中作三十首 其二十","f":"五言律诗","c":["宦名浑不计，酒熟且开封。","晴月销灯色，寒天挫笔锋。","惊禽时并起，闲客数相逢。","旧国萧条思，青山隔几重。"]},{"t":"武功县中作三十首 其二十一","f":"五言律诗","c":["假日多无事，谁知我独忙。","移山入县宅，种竹上城墙。","惊蝶遗花蕊，游蜂带蜜香。","唯愁明早出，端坐吏人旁。"]},{"t":"武功县中作三十首 其二十二","f":"五言律诗","c":["门外青山路，因循自不归。","养生宜县僻，说品喜官微。","净爱山僧饭，闲披野客衣。","谁怜幽谷鸟，不解入城飞。"]},{"t":"武功县中作三十首 其二十三","f":"五言律诗","c":["一官无限日，愁闷欲何如。","扫舍惊巢燕，寻方落壁鱼。","从僧乞净水，凭客报闲书。","白发谁能镊，年来四十馀。"]},{"t":"武功县中作三十首 其二十四","f":"五言律诗","c":["朝朝门不闭，长似在山时。","宾客抽书读，儿童斫竹骑。","久贫还易老，多病懒能医。","道友应相怪，休官日已迟。"]},{"t":"武功县中作三十首 其二十五","f":"五言律诗","c":["戚戚常无思，循资格上官。","闲人得事晚，常骨觅仙难。","醉卧疑身病，贫居觉道宽。","新诗久不写，自算少人看。"]},{"t":"武功县中作三十首 其二十六","f":"五言律诗","c":["漫作容身计，今知拙有馀。","青衫迎驿使，白发忆山居。","道友怜蔬食，吏人嫌草书。","须为长久事，归去自耕锄。"]},{"t":"武功县中作三十首 其二十七","f":"五言律诗","c":["主印三年坐，山居百事休。","焚香开敕库，踏月上城楼。","饮酒多成病，吟诗易长愁。","慇勤问渔者，暂借手中钩。"]},{"t":"武功县中作三十首 其二十八","f":"五言律诗","c":["长忆青山下，深居遂性情。","垒阶溪石净，烧竹灶烟轻。","点笔图云势，弹琴学鸟声。","今朝知县印，梦里百忧生。"]},{"t":"武功县中作三十首 其二十九","f":"五言律诗","c":["自知狂僻性，吏事固相疏。","祗是看山立，无嫌出县居。","印朱沾墨砚，户籍杂经书。","月俸寻常请，无妨乏斗储。"]},{"t":"武功县中作三十首 其三十","f":"五言律诗","c":["作吏无能事，为文旧致功。","诗标八病外，心落百忧中。","拜别登朝客，归依鍊药翁。","不知还往内，谁与此心同。"]},{"t":"陕下厉玄侍御宅五题 竹里径","f":"五言律诗","c":["微径婵娟里，唯闻静者知。","迹深苔长处，步狭笋生时。","高是连幽树，穷应到曲池。","纱巾灵寿杖，行乐复相宜。"]},{"t":"陕下厉玄侍御宅五题 吟诗岛","f":"五言律诗","c":["幽岛藓层层，诗人日日登。","坐危石是榻，吟冷唾成冰。","静对唯秋水，同来但老僧。","竹枝题字处，小篆复谁能。"]},{"t":"陕下厉玄侍御宅五题 泛觞泉","f":"五言律诗","c":["不上酒家楼，池边日献酬。","杯来转巴字，客坐绕方流。","酹滴苔纹断，泉连石岸秋。","若能山下置，岁晚愿同游。"]},{"t":"陕下厉玄侍御宅五题 垂钓亭","f":"五言律诗","c":["由钓起茅亭，柴扉复竹楹。","波清见丝影，坐久识鱼情。","白鸟依窗宿，青蒲傍砌生。","欲同渔父舍，须自减逢迎。"]},{"t":"陕下厉玄侍御宅五题 濯缨溪","f":"五言律诗","c":["旧山宁要去，此有濯缨泉。","晓景松枝覆，秋光月色连。","行寻屐齿尽，坐对角巾偏。","寂寂幽栖处，无妨请俸钱。"]},{"t":"陕城即事","f":"五言律诗","c":["左右分京阙，黄河与宅连。","何功来此地，窃位已经年。","天下才弥小，关中镇最先。","陇山望可见，惆怅是穷边。"]},{"t":"亲仁里居","f":"七言律诗","c":["三年赁舍亲仁里，寂寞何曾似在城。","饮酒自缘防冷病，寻人多是为闲行。","轩车无路通门巷，亲友因诗道姓名。","自别青山归未得，羡君长听石泉声。"]},{"t":"剑器词三首 其一","f":"五言律诗","c":["圣朝能用将，破敌速如神。","掉剑龙缠臂，开旗火满身。","积尸川没岸，流血野无尘。","今日当场舞，应知是战人。"]},{"t":"剑器词三首 其二","f":"五言律诗","c":["昼渡黄河水，将军险用师。","雪光偏著甲，风力不禁旗。","阵变龙蛇活，军雄鼓角知。","今朝重起舞，记得战酣时。"]},{"t":"剑器词三首 其三","f":"五言律诗","c":["破虏行千里，三军意气粗。","展旗遮日黑，驱马饮河枯。","邻境求兵略，皇恩索阵图。","元和太平乐，自古恐应无。"]},{"t":"客舍有怀","f":"五言律诗","c":["旅人无事喜，终日思悠悠。","逢酒嫌杯浅，寻书怕字稠。","贫来许钱圣，梦觉见身愁。","寂寞中林下，饥鹰望到秋。"]},{"t":"客游旅怀","f":"五言律诗","c":["客行无定止，终日路岐间。","马为赊来贵，僮缘借得顽。","诗书愁触雨，店舍喜逢山。","旧业嵩阳下，三年未得还。"]},{"t":"将归山","f":"七言律诗","c":["野人惯去山中住，自到城来闷不胜。","宫树蝉声多却乐，侯门月色少于灯。","饥来唯拟重餐药，归去还应只别僧。","闻道旧溪茆屋畔，春风新上数枝藤。"]},{"t":"春日同会卫尉崔少卿宅","f":"五言律诗","c":["诗家会诗客，池阁晓初晴。","鸟尽山中语，琴多谱外声。","映花相劝酒，入洞各题名。","疏野常如此，谁人信在城。"]},{"t":"春日早朝寄刘起居","f":"五言律诗","c":["九衢寒雾敛，双阙曙光分。","綵杖迎春日，香烟接瑞云。","佩声清漏间，天语侍臣闻。","莫笑冯唐老，还来谒圣君。"]},{"t":"春日江次","f":"五言律诗","c":["野步出茆斋，闲行坐石台。","久悲乡路远，犹喜杏花开。","鸥鹭皆飞去，帆樯何处来？","因凝千里目，落日尚徘徊。"]},{"t":"春日即事","f":"五言律诗","c":["春来眠不得，谁复念生涯。","夜听四邻乐，朝寻九陌花。","轻烟浮草色，微雨濯年华。","乞假非关病，朝衣在酒家。"]},{"t":"春日闲居","f":"五言律诗","c":["居止日萧条，庭前唯药苗。","身闲眠自久，眼荖视还遥。","檐燕酬莺语，邻花杂絮飘。","客来无酒饮，搔首掷空瓢。"]},{"t":"春晚雨中","f":"五言律诗","c":["寂寂春将老，闲人强自欢。","迎风莺语涩，带雨蝶飞难。","傍砌木初长，眠花景渐阑。","临轩平目望，情思若为宽。"]},{"t":"洛下夜会寄贾岛","f":"五言律诗","c":["洛下攻诗客，相逢祗是吟。","夜觞欢稍静，寒屋坐多深。","乌府偶为吏，沧江长在心。","忆君难就寝，烛灭复星沈。"]},{"t":"独居","f":"七言律诗","c":["深闭柴门长不出，功夫自课少闲时。","翻音免问他人字，覆局何劳对手棋。","生计如云无定所，穷愁似影每相随。","到头归向青山是，尘路茫茫欲告谁。"]},{"t":"秋夕遣怀","f":"五言律诗","c":["昨宵白露下，秋气满山城。","风劲衣巾脆，窗虚笔墨轻。","临书爱真迹，避酒怕狂名。","祗拟随麋鹿，悠悠过一生。"]},{"t":"秋日书事寄秘书窦少监","f":"五言律诗","c":["秋气日骚骚，星星双鬓毛。","凉天吟自远，清夜梦还高。","林下期同去，人间共是劳。","头巾何所直，且漉瓮头糟。"]},{"t":"秋日有怀","f":"五言律诗","c":["秋来不复眠，但觉思悠然。","菊色欲经露，虫声渐替蝉。","诗情生酒里，心事在山边。","旧里无因到，西风又一年。"]},{"t":"秋日闲居二首 其一","f":"五言律诗","c":["九陌宅重重，何门怜此翁。","荒庭唯菊茂，幽径与山通。","落叶带衣上，闲云来酒中。","此心谁得见，林下鹿应同。"]},{"t":"秋日闲居二首 其二","f":"五言律诗","c":["先忆花时节，家山听更归。","爱诗看古集，忆酒典寒衣。","睡少身还健，愁多食不肥。","自怜疏懒性，无事出门稀。"]},{"t":"秋日寄李支使","f":"五言律诗","c":["秋思朝来起，侵人暑稍微。","晓眠离北户，午饭尚生衣。","山静云初白，枝高果渐稀。","闻君家海上，莫与燕同归。"]},{"t":"秋夜月中登天坛","f":"五言律诗","c":["秋蟾流异彩，斋洁上坛行。","天近星辰大，山深世界清。","仙飙石上起，海日夜中明。","何计长来此，闲眠过一生。"]},{"t":"秋夜寄默然上人","f":"五言律诗","c":["霜月静幽居，闲吟梦觉初。","秋深夜迢遰，年长意萧疏。","海上归难遂，人间事尽虚。","赖师方便语，渐得识真如。"]},{"t":"秋晚江次","f":"五言律诗","c":["萧萧晚景寒，独立望江壖。","沙渚几行雁，风湾一只船。","落霞澄返照，孤屿隔微烟。","极目思无尽，乡心到眼前。"]},{"t":"秋晚夜坐寄院中诸曹长","f":"五言律诗","c":["腰间垂印囊，白发未归乡。","还往应相责，朝昏亦自伤。","穷愁山影峭，独夜漏声长。","寂寞难成寐，寒灯侵晓光。"]},{"t":"种苇","f":"五言律诗","c":["欲种数茎苇，出门来往频。","近陂收本土，选地问幽人。","静看唯思长，初移未觉匀。","坐中寻竹客，将去更逡巡。"]},{"t":"荅友人招游","f":"五言律诗","c":["不来知尽怪，失意懒春游。","闻鸟宁惊梦，看花怕引愁。","赌棋招敌手，沽酒自扶头。","何似华筵上，推辞候到筹。"]},{"t":"荅李频秀才","f":"五言律诗","c":["一年离九陌，壁上挂朝袍。","物外诗情远，人间酒味高。","思归知病长，失寝觉神劳。","衰老无多思，因君把笔毫。"]},{"t":"荅胡遇","f":"五言律诗","c":["一会一分离，贫游少定期。","酒多为客稳，米贵入城迟。","晴日偷将睡，秋山乞与诗。","纵然眉得展，不似见君时。"]},{"t":"送丁端公赴河阴","f":"五言律诗","c":["炎天木叶焦，晓夕绝凉飙。","念子独归县，何人不在朝。","市连风浪动，帆彻海门遥。","饮尽樽中酒，同年同寂寥。"]},{"t":"送马戴下第客游","f":"五言律诗","c":["昨来送君处，亦是九衢中。","此日慇勤别，前时寂寞同。","鸟啼寒食雨，花落暮春风。","向晚离人起，筵收樽未空。"]},{"t":"送元绪上人游商山","f":"五言律诗","c":["万法空门里，师修历几生。","过来心已悟，未到行弥精。","溪寂钟还度，林昏锡独鸣。","朝簪抽未得，此别岂忘情。"]},{"t":"送友人游蜀","f":"五言律诗","c":["送君一壶酒，相别野庭边。","马上过秋色，舟中到锦川。","峡猿啼夜雨，蜀鸟噪晨烟。","莫便不回首，风光促几年。"]},{"t":"送少府田中丞入西藩","f":"五言律诗","c":["萧关路绝久，石堠亦为尘。","护塞空兵帐，和戎在使臣。","风沙去国远，雨雪换衣频。","若问凉州事，凉州多汉人。"]},{"t":"送文著上人游越","f":"七言律诗","c":["水石随缘岂计程，东吴相遇别西京。","夜禅月下袈裟湿，晓上山巅锡杖鸣。","念我为官应易老，羡师依佛学无生。","越中多有前朝寺，处处铁钟石磬声。"]},{"t":"送无可上人游边","f":"五言律诗","c":["一钵与三衣，经行远近随。","出家还养母，持律复能诗。","春雪离京厚，晨钟近塞迟。","亦知莲府客，夜坐喜同师。"]},{"t":"送无可上人游越","f":"七言律诗","c":["清晨相访立门前，麻履方袍一少年。","懒读经文求作佛，愿攻诗句觅升仙。","芳春山影花连寺，独夜潮声月满船。","今日送行偏惜别，共师文字有因缘。"]},{"t":"送王龟处士","f":"五言律诗","c":["送客客为谁，朱门处士稀。","唯修曾子行，不著老莱衣。","古寺随僧饭，空林共鸟归。","壶中驻年药，烧得献庭闱。"]},{"t":"送王建秘书往渭南庄","f":"五言律诗","c":["白须芸阁吏，羸马月中行。","庄僻难寻路，官闲易出城。","看山多失饭，过寺故题名。","秋日田家作，唯添集卷成。"]},{"t":"送王嗣之典仪城","f":"五言律诗","c":["日日思朝位，偷闲城外行。","唯求采药者，不道在官名。","好异嫌山浅，寻幽喜径生。","病来文字拙，不要把归城。"]},{"t":"送王澹","f":"五言律诗","c":["常省为官处，门前数树松。","寻山屐费齿，书石笔无锋。","果熟猿偷乱，花繁鸟语重。","今来为客去，惜取最高峰。"]},{"t":"送韦瑶校书赴越","f":"五言律诗","c":["寄家临禹穴，乘传出秦关。","霜落橘满地，潮来帆近山。","相门宾益贵，水国事多闲。","晨省高堂后，馀欢杯酒间。"]},{"t":"送卢二弟茂才罢举游洛谒新相","f":"五言律诗","c":["踏碎作赋笔，驱车出上京。","离筵俯岐路，四坐半公卿。","守命贫难掷，忧身梦数惊。","今朝赴知己，休咏苦辛行。"]},{"t":"送右司薛员外赴处州","f":"五言律诗","c":["怀中天子书，腰下使君鱼。","瀑布和云落，仙都与世疏。","远程兼水陆，半岁在舟车。","相送难相别，南风入夏初。"]},{"t":"送田使君赴蔡州","f":"五言律诗","c":["长年离别情，百盏酒须倾。","诗外应无思，人间半是行。","路遥嘶白马，林断出红旌。","功业今应立，淮西有劲兵。"]},{"t":"送任尊师归蜀觐亲","f":"五言律诗","c":["白云修道者，归去春风前。","玉简通仙籍，金丹驻母年。","锦文江一色，酒气雨相连。","众说君平死，真师易义全。"]},{"t":"送任畹及第归蜀中觐亲","f":"五言律诗","c":["子规啼欲死，君听固无愁。","阙下声名出，乡中意气游。","东川横剑阁，南斗近刀州。","神圣题前字，千人看不休。"]},{"t":"送刘禹锡郎中赴苏州 其一","f":"七言律诗","c":["三十年来天下名，衔恩东守阖闾城。","初经咸谷眠山驿，渐入梁园问水程。","霁日满江寒浪静，春风绕郭白蘋生。","虎丘野寺吴中少，谁伴吟诗月里行。"]},{"t":"送刘禹锡郎中赴苏州 其二","f":"七言律诗","c":["州城全是故吴宫，香径难寻古藓中。","云水计程千里远，轩车送别九衢空。","鹤声高下听无尽，潮色朝昏望不同。","太守吟诗人自理，小斋闲卧白蘋风。"]},{"t":"送刘詹事赴寿州","f":"五言律诗","c":["慇勤莫遽起，四坐悉同袍。","世上诗难得，林中酒更高。","隋堤傍杨柳，楚驿在波涛。","别后书频寄，无辞费笔毫。"]},{"t":"送孙山人","f":"五言律诗","c":["山翁来帝里，不肯住多时。","尘土衣裳重，腥膻仆隶饥。","林中愁不到，城外老应迟。","喧寂一为别，相逢未有期。"]},{"t":"送朱庆馀及第后归越","f":"五言律诗","c":["劝君缓上车，乡里有吾庐。","未得同归去，空令相见疏。","山晴栖鹤起，天晓落潮初。","此庆将谁比，献亲冬集书。"]},{"t":"送朱庆馀越州归觐","f":"五言律诗","c":["乡书落姓名，太守拜亲荣。","访我波涛郡，还家雾雨城。","海山窗外近，镜水世间清。","何计随君去，邻墙过此生。"]},{"t":"送邢郎中赴太原","f":"五言律诗","c":["上将得良策，恩威作长城。","如今并州北，不见有胡兵。","晋野雨初足，汾河波亦清。","所从古无比，意气送君行。"]},{"t":"送别友人","f":"七言律诗","c":["独向山中觅紫芝，山人勾引住多时。","摘花浸酒春愁尽，烧竹煎茶夜卧迟。","泉落林梢多碎滴，松生石底足旁枝。","明朝却欲归城市，问我来期总不知。"]},{"t":"送宋慎言","f":"五言律诗","c":["童稚便知闻，如今祗有君。","百篇诗尽和，一盏酒须分。","驿路多连水，州城半在云。","离情同落叶，向晚更纷纷。"]},{"t":"送张郎中副使赴泽潞","f":"五言律诗","c":["晓陌事戎装，风流粉署郎。","机筹通变化，除拜出寻常。","地冷饶霜气，山高碍雁行。","应无离别恨，车马自生光。"]},{"t":"送李传秀才归宣州","f":"五言律诗","c":["谢守青山宅，山孤宅亦平。","池塘无复见，春草野中生。","常日登楼望，今朝送客行。","慇勤拂石壁，为我一书名。"]},{"t":"送李秀才赴举","f":"五言律诗","c":["罗刹楼头醉，送君西入京。","秦吴无限地，山水半分程。","海上烟霞湿，关中日月明。","登科旧乡里，当为改嘉名。"]},{"t":"送李侍御过夏州","f":"五言律诗","c":["酬恩不顾名，走马觉身轻。","迢递河边路，苍茫塞上城。","沙寒无宿雁，虏近少闲兵。","饮罢挥鞭去，旁人意气生。"]},{"t":"送李起居赴池州","f":"五言律诗","c":["天子念疲民，分忧辍侍臣。","红旗高起焰，绿野静无尘。","阙下亲知别，江南惠化新。","朝昏即千里，且愿话逡巡。"]},{"t":"送李植侍御","f":"五言律诗","c":["圣代无邪触，空林獬豸归。","谁知陇山鸟，长绕玉楼飞。","风雨依山急，云泉入郭微。","无同昔年别，别后寄书稀。"]},{"t":"送李琮归灵州觐省","f":"五言律诗","c":["饯席离人起，贪程醉不眠。","风沙移道路，仆马识山川。","塞树花开小，关城雪下偏。","胡尘今已尽，应便促朝天。"]},{"t":"送李廓侍御赴西川行营","f":"五言律诗","c":["不道弓箭字，罢官唯醉眠。","何人荐筹策，走马逐旌旃。","阵变孤虚外，功成语笑前。","从今巂州路，无复有烽烟。"]},{"t":"送杜观罢举东游","f":"五言律诗","c":["秋风离九陌，心事岂云安。","曾是求名苦，当知此去难。","辛勤程自远，寂寞夜多寒。","诗句无人识，应须把剑看。"]},{"t":"送杨尚书赴东川","f":"五言律诗","c":["郤縠诗书将，衔恩赴梓州。","绕身垂印绶，护马执戈矛。","剑阁和铭峭，巴江带字流。","从来皆惜别，此别复何愁。"]},{"t":"送进士田卓入华山","f":"五言律诗","c":["何物随身去，六经与一琴。","辞家计已久，入谷住应深。","偶坐僧同石，闲书叶满林。","业成须谒帝，无贮白云心。"]},{"t":"送陈倜赴江陵从事","f":"七言律诗","c":["荆州胜事众皆闻，幕下今朝又得君。","才子何须藉科第，男儿终久要功勋。","江村竹树多于草，山路尘埃半是云。","新什定知饶景思，不应一向赋从军。"]},{"t":"送林使君赴邵州","f":"七言律诗","c":["诏书飞下五云间，才子分符不等闲。","驿路算程多是水，州图管地少于山。","江头斑竹寻应遍，洞里丹砂自采还。","清净化人人自理，终朝无事更相关。"]},{"t":"送河中杨少府宴崔驸马宅","f":"七言律诗","c":["凤凰楼下醉醺醺，晚出东门蝉渐闻。","不使乡人治驿路，却将家累宿山云。","闲时采药随僧去，每月请钱共客分。","县吏若非三载满，自知无计更寻君。"]},{"t":"送郑尚书赴兴元","f":"五言律诗","c":["儒有登坛贵，何人得此功。","红旗烧密雪，白马踏长风。","斧钺来天上，诗书理汉中。","方知百胜略，应不在弯弓。"]},{"t":"送春","f":"五言律诗","c":["昨迎今复送，来晚去逡巡。","芳尽空繁树，愁多独病身。","静思倾酒懒，闲望上楼频。","为向春风道，明年早报春。"]},{"t":"送洛阳张员外","f":"五言律诗","c":["饯客未归城，东来驺骑迎。","千山嵩岳峭，百县洛阳清。","朔雁和云度，川风吹雨晴。","藓庭公事暇，应祗独吟行。"]},{"t":"送独孤焕评事赴丰州","f":"七言律诗","c":["东门携酒送廷评，结束从军塞上行。","深碛路移唯马觉，断蓬风起与雕平。","烟生远戍侵云色，冰叠黄河长雪声。","须凿燕然山上石，登科记里是闲名。"]},{"t":"送费骧","f":"五言律诗","c":["兄寒弟亦饥，力学少闲时。","何路免为客，无门卖得诗。","几人携酒送，独我入山迟。","少小同居止，今朝始别离。"]},{"t":"送陟遐上人游天台","f":"五言律诗","c":["万叠赤城路，终年游客稀。","朝来送师去，自觉有家非。","石净山光远，云深海色微。","此诗成亦鄙，为我写岩扉。"]},{"t":"送饶州张使君","f":"七言律诗","c":["鄱阳胜事闻难比，千里连连是稻畦。","山寺去时通水路，郡图开处是诗题。","化行应免农人困，庭静惟多野鹤栖。","饮罢春明门外别，萧条驿路夕阳低。"]},{"t":"送徐州韦仅行军","f":"五言律诗","c":["饯幕俨征轩，行军归大藩。","山程度函谷，水驿到夷门。","晓日诗情远，春风酒色浑。","逡巡何足贵，所贵尽残樽。"]},{"t":"送徐员外赴河中从事","f":"五言律诗","c":["赤府从军美，儒衣结束轻。","凉飙下山寺，晓浪满关城。","闲坐饶诗景，高眠长道情。","将军不战术，计日立功名。"]},{"t":"送殷尧藩侍御赴同州","f":"五言律诗","c":["吟诗掷酒船，仙掌白楼前。","从事关中贵，主人天下贤。","此生无了日，终岁踏离筵。","何计因归去，深山恣意眠。"]},{"t":"送殷尧藩侍御游山南","f":"五言律诗","c":["诗境西南好，秋深昼夜蛩。","人家连水影，驿路在山峰。","谷静云生石，天寒雪覆松。","我为公府系，不得此相从。"]},{"t":"送贾谟赴共城营田","f":"五言律诗","c":["上国羞长选，戎装贵所从。","山田依法种，兵食及时供。","水气诗书软，岚烟笔砚浓。","几时无事扰，相见得从容。"]},{"t":"送顾非熊下第归越","f":"五言律诗","c":["失意寻归路，亲知不复过。","家山去城远，日月在船多。","楚塞数逢雁，浙江长有波。","秋风别乡老，还听鹿鸣歌。"]},{"t":"送崔之仁","f":"五言律诗","c":["欲出还成住，前程甚谪迁。","佯眠随客醉，愁坐似僧禅。","旧国归何处，春山买欠钱。","几时无一事，长在故人边。"]},{"t":"送崔中丞赴郑州","f":"五言律诗","c":["仆射陂前郡，清高越四邻。","丹霄凤诏下，太守虎符新。","雾湿关城月，花香驿路尘。","连枝相庭树，岁岁一家春。"]},{"t":"送崔约下第归扬州","f":"七言律诗","c":["满座诗人吟送酒，离城此会亦应稀。","春风下第时称屈，秋卷呈亲自束归。","日晚山花当马落，天阴水鸟傍船飞。","江边道路多苔藓，尘土无由得上衣。"]},{"t":"送崔郎中赴常州","f":"七言律诗","c":["贵是鸰原在紫微，荣逢知己领黄扉。","人间盛事今全得，江上政声复欲归。","风起满城山果落，雨馀穿宅水禽飞。","昔年尝作毗陵客，石峭泉清天下稀。"]},{"t":"送清敬阇黎归浙西","f":"五言律诗","c":["大地无生理，吴中岂是归。","自翻贝叶偈，人施福田衣。","夏尽滩声出，潮来日色微。","郡斋师去后，寂寞夜吟稀。"]},{"t":"送盛秀才赴举","f":"七言律诗","c":["重重吴越浙江潮，刺史何门始得消。","五字州人唯有此，四邻风景合相饶。","橘村篱落香潜度，竹寺虚空翠自飘。","君去九衢须说我，病成疏懒懒趋朝。"]},{"t":"送萧正字往蔡州贺裴相淮西平","f":"五言律诗","c":["相府旌旄重，还邀上客行。","今朝郭门路，初彻蔡州城。","从马唯提酒，防身不要兵。","从来皆作使，君去是时平。"]},{"t":"送喻凫校书归毗陵","f":"五言律诗","c":["主人庭叶黑，诗稿更谁书。","阙下科名出，乡中赋籍除。","山春烟树众，江远晚帆疏。","吾亦家吴者，无因到弊庐。"]},{"t":"送董正字武归常州觐亲","f":"五言律诗","c":["路岐知不尽，离别自无穷。","行客心方切，主人樽未空。","楚樯收月下，江树在潮中。","人各还家去，还家庆不同。"]},{"t":"送源中丞赴新罗","f":"七言律诗","c":["赤墀赐对使殊方，官重霜台紫绶光。","玉节在船清海怪，金函开诏拜夷王。","云晴渐觉山川异，风便那知道路长。","谁得似君将雨露，海东万里洒扶桑。"]},{"t":"送雍陶及第归觐","f":"五言律诗","c":["献亲冬集书，比橘复何如。","此去关山远，相思笑语疏。","路寻丹壑断，人近白云居。","幽石题名处，凭君亦记余。"]},{"t":"送雍陶游蜀","f":"五言律诗","c":["春色三千里，愁人意未开。","木梢穿栈出，雨势隔江来。","荒馆因花宿，深山羡客回。","相如何物在，应只有琴台。"]},{"t":"送僧贞实归杭州天竺","f":"七言律诗","c":["石桥寺里最清凉，闻说茆庵寄上方。","林外猿声连院磬，月中潮色到禅床。","他生念我身何在，此世唯师性亦忘。","九陌相逢千里别，青山重叠树苍苍。"]},{"t":"送僧栖真归杭州天竺寺","f":"五言律诗","c":["吏事日纷然，无因到佛前。","劳师相借问，知我亦通禅。","古寺杉松出，残阳钟磬连。","草庵盘石上，归此是因缘。"]},{"t":"送僧游边","f":"五言律诗","c":["师向边头去，边人业障轻。","腥膻斋自洁，部落讲还成。","传教多离寺，随缘不计程。","三千世界内，何处是无生。"]},{"t":"送僧默然","f":"五言律诗","c":["出家侍母前，至孝自通禅。","伏日江头别，秋风樯下眠。","鸟声猿更促，石色树相连。","此路多如此，师行亦有缘。"]},{"t":"送裴中丞赴华州","f":"五言律诗","c":["我梦何曾应，看君渡浐川。","自无仙掌分，非是圣心偏。","径草多生药，庭花半落泉。","人间有此郡，况在凤城边。"]},{"t":"送裴宰君","f":"五言律诗","c":["见说为官处，烟霞思不穷。","夜猿啼户外，瀑水落厨中。","名药人难识，仙山路易通。","还应施静化，谁复与君同。"]},{"t":"送潘传秀才归宣州","f":"五言律诗","c":["李白坟三尺，嵯峨万古名。","因君还故里，为我吊先生。","晴日移虹影，空山出鹤声。","老郎闲未得，无计此中行。"]},{"t":"送澄江上人赴兴元郑尚书招","f":"五言律诗","c":["师经非纸上，师佛在心中。","觉路何曾异，行人自不同。","水云晴亦雨，山木夜多风。","闻结西方社，尚书待远公。"]},{"t":"郡中书事寄默然上人","f":"五言律诗","c":["郡中饶野兴，过客亦淹留。","看月江楼晓，寻山石径秋。","意归何处老，谁免此生愁。","长爱东林子，安禅百事休。"]},{"t":"郡中冬夜闻蛩","f":"五言律诗","c":["秋蛩声尚在，切切起苍苔。","久是忘情者，今还有事来。","微霜风稍静，圆月雾初开。","此思谁能遣，应须执酒杯。"]},{"t":"郡中对雪","f":"五言律诗","c":["霏微著草树，渐布与阶平。","远近如空色，飘飏无落声。","飞鸦疑翅重，去马觉蹄轻。","遥想故山下，樵夫应滞行。"]},{"t":"闻蝉寄贾岛","f":"五言律诗","c":["秋来吟更苦，半咽半随风。","禅客心应乱，愁人耳愿聋。","雨晴烟树里，日晚古城中。","远思应难尽，谁当与我同。"]},{"t":"闻魏州破贼","f":"七言律诗","c":["生灵苏息到元和，上将功成自执戈。","烟雾扫开尊北岳，蛟龙斩断净南河。","旗回海眼军容壮，兵合天心杀气多。","从此四方无一事，朝朝雨露是恩波。"]},{"t":"除夜二首 其一","f":"五言律诗","c":["衰残归未遂，寂寞此宵情。","旧国当千里，新年隔数更。","寒犹近北峭，风渐向东生。","谁见长安陌，晨钟度火城。"]},{"t":"哭砚山孙道士","f":"五言律诗","c":["修短皆由命，暗怀师出尘。","岂知修道者，难免不亡身。","永秘黄庭诀，高悬漉酒巾。","可怜白犬子，闲吠远行人。"]},{"t":"哭费拾遗徵君","f":"五言律诗","c":["服儒师道旨，粝食卧中林。","谁识先生事，无身是本心。","空山流水远，故国白云深。","日夕谁来哭，唯应猿鸟吟。"]},{"t":"哭贾岛二首 其一","f":"五言律诗","c":["白日西边没，沧波东去流。","名虽千古在，身已一生休。","岂料文章远，那知瑞草秋。","曾闻有书剑，应是别人收。"]},{"t":"哭贾岛二首 其二","f":"五言律诗","c":["杳杳黄泉下，嗟君向此行。","有名传后世，无子过今生。","新墓松三尺，空阶月二更。","从今旧诗卷，人觅写应争。"]},{"t":"夏日书事寄丘亢处士","f":"五言律诗","c":["暑天难可度，岂复更持觞。","树里鸣蝉咽，宫中午漏长。","病夫心益躁，静者室应凉。","几欲相寻去，红尘满路旁。"]},{"t":"夏日登楼晚望","f":"五言律诗","c":["避暑高楼上，平芜望不穷。","鸟穿山色去，人歇树阴中。","数带长河水，千条弱柳风。","暗思多少事，懒话与芝翁。"]},{"t":"夏夜","f":"五言律诗","c":["闲斋深夜静，独坐又闲行。","密树月笼影，疏篱水隔声。","断猿时叫谷，栖鸟每摇柽。","寂寞求名士，谁知此夕情。"]},{"t":"夏夜宿江驿","f":"五言律诗","c":["竹屋临江岸，清宵兴自长。","夜深倾北斗，叶落映横塘。","渚闹渔歌响，风和角粽香。","却愁南去棹，早晚到潇湘。"]},{"t":"宴光禄田卿宅","f":"五言律诗","c":["竹里开华馆，珍羞次第尝。","春风酒影动，晴日乐声长。","久坐难辞醉，衰年亦暂狂。","慇勤还继烛，永夕梦相妨。"]},{"t":"病中辱谏议惠甘菊药苗因以诗赠","f":"五言律诗","c":["萧萧一亩宫，种菊十馀丛。","采摘和芳露，封题寄病翁。","熟宜茶鼎里，餐称石瓯中。","香洁将何比，从来味不同。"]},{"t":"病僧","f":"五言律诗","c":["三年病不出，苔藓满藤鞋。","倚壁看经坐，闻钟吃药斋。","茶烟熏杀竹，檐雨滴穿阶。","无暇频相访，秋风寂寞怀。"]},{"t":"罢武功县将入城 其一","f":"七言律诗","c":["乍抛衫笏觉身轻，依旧还称学道名。","欲泥山僧分屋住，羞从野老借牛耕。","妻儿尽怕为逋客，亲故相邀遣到城。","无奈同官珍重意，几回临路却休行。"]},{"t":"罢武功县将入城 其二","f":"七言律诗","c":["青衫脱下便狂歌，种薤栽莎斸古坡。","野客相逢添酒病，春山暂上著诗魔。","亦知官罢贫还甚，且喜闲来睡得多。","欲与九衢亲故别，明朝拄杖始经过。"]},{"t":"假日书事呈院中司徒","f":"五言律诗","c":["十日公府静，巾栉起清晨。","寒蝉近衰柳，古木似高人。","学佛宁忧老，为儒自喜贫。","海山归未得，芝朮梦中春。"]},{"t":"偶然书怀","f":"七言律诗","c":["十年通籍入金门，自愧名微枉搢绅。","鍊得丹砂疑不食，从兹白发日相亲。","家山迢遰归无路，杯酒稀疏病到身。","汉有冯唐唐有我，老为郎吏更何人。"]},{"t":"偶题","f":"七言律诗","c":["年年九陌看春还，旧隐空劳梦寐间。","迟日逍遥芸草长，圣朝清净谏臣闲。","偶逢游客同倾酒，自有前驺耻见山。","道侣书来相责诮，朝朝欲报作何颜。"]},{"t":"寄卫拾遗乞酒","f":"五言律诗","c":["老人罢卮酒，不醉已经年。","自饮君家酒，一杯三日眠。","味轻花上露，色似洞中泉。","莫厌时时寄，须知法未传。"]},{"t":"寄山中友人","f":"五言律诗","c":["昨秋今复春，役役是非身。","海上无归路，城中作老人。","流年何处在，白日每朝新。","闻有长生术，将求未有因。"]},{"t":"寄马戴","f":"五言律诗","c":["天府鹿鸣客，幽山秋未归。","我知方甚爱，众说以为非。","隔屋闻泉细，和云见鹤微。","新诗此处得，清峭比应稀。"]},{"t":"寄不出院僧","f":"五言律诗","c":["不行门外地，斋戒得清真。","长食施来饭，深居锁定身。","朝昏常傍佛，起坐省逢人。","非独心常净，衣无一点尘。"]},{"t":"寄不疑上人","f":"五言律诗","c":["是法修行遍，方栖不二门。","随缘嫌寺著，见性觉经繁。","所叹身将老，始闻师一言。","尘沙千万劫，劫尽佛长存。"]},{"t":"寄元绪上人","f":"五言律诗","c":["石窗紫藓墙，此世此清凉。","研露题诗洁，消冰煮茗香。","闲云春影薄，孤磬夜声长。","何计休为吏，从师老草堂。"]},{"t":"寄友人","f":"五言律诗","c":["日暮掩重扉，抽簪复解衣。","漏声林下静，萤色月中微。","秋霁露华结，夜深人语稀。","慇勤故山路，谁与我同归。"]},{"t":"寄无可上人","f":"五言律诗","c":["十二门中寺，诗僧寺独幽。","多年松色别，后夜磬声秋。","见世虑皆尽，来生事更修。","终须执瓶钵，相逐入牛头。"]},{"t":"寄东都分司白宾客","f":"七言律诗","c":["阙下高眠过十旬，南宫印绶乞离身。","诗中得意应千首，海内嫌官只一人。","宾客分司真是隐，山泉绕宅岂辞贫。","竹斋晚起多无事，唯到龙门寺里频。"]},{"t":"寄主客刘员外","f":"五言律诗","c":["蝉稀虫唧唧，露重思悠悠。","静者多便夜，豪家不见秋。","同归方欲就，微恙几时瘳。","今日沧江上，何人理钓舟。"]},{"t":"寄主客刘郎中","f":"七言律诗","c":["汉朝共许贾生贤，迁谪还应是宿缘。","仰德多时方会面，拜兄何暇更论年。","嵩山晴色来城里，洛水寒光出岸边。","清景早朝吟丽思，题诗应费益州笺。"]},{"t":"寄永乐长官殷尧藩","f":"五言律诗","c":["故人为吏隐，高卧簿书间。","绕院唯栽药，逢僧只说山。","此宵欢不接，穷岁信空还。","何计相寻去，严风雪满关。"]},{"t":"寄白石师","f":"五言律诗","c":["白石师何在，师禅白石中。","无情云可比，不食鸟难同。","屦下苍苔雪，龛前瀑布风。","相寻未有计，只是礼虚空。"]},{"t":"寄白阁默然","f":"五言律诗","c":["白阁峰头雪，城中望亦寒。","高僧多默坐，清夜到明看。","世上无诸苦，林间只一餐。","尝闻南北教，所得比师难。"]},{"t":"寄华州崔中丞","f":"五言律诗","c":["莲华峰下郡，仙洞亦难胜。","闾里苍苔水，虚空瀑布冰。","酒香和药熟，山峭过云登。","清净黎人泰，唯忧急诏徵。"]},{"t":"寄孙路秀才","f":"五言律诗","c":["幽居邻里少，江际复山阿。","潮去蝉声出，天晴鹤语多。","老人能步蹇，才子奈贫何。","曾见春官语，年来虚甲科。"]},{"t":"寄安陆友人","f":"五言律诗","c":["别路在春色，故人云梦中。","鸟啼三月雨，蝶舞百花风。","烟束远山碧，霞欹落照红。","想君登此兴，回首念飘蓬。"]},{"t":"寄张徯","f":"五言律诗","c":["幽处寻书坐，朝朝闭竹扉。","山僧封茗寄，野客乞诗归。","秋卷多唯好，时名屈更肥。","明年取前字，杯酒赛春辉。"]},{"t":"寄李频","f":"五言律诗","c":["闭门常不出，惟觉长庭莎。","朋友来看少，诗书卧读多。","命随才共薄，愁与醉相和。","珍重君名字，新登甲乙科。"]},{"t":"寄杜师义","f":"五言律诗","c":["出处难相见，同城似异乡。","点兵寻户籍，烧药试仙方。","事校千般别，心还一种忙。","黄金如化得，相寄亦何妨。"]},{"t":"寄汴州令狐楚相公","f":"七言律诗","c":["汴水从今不复浑，秋风鼙鼓动城根。","梁园台馆关东少，相府旌旗天下尊。","诗好四方谁敢和，政成三郡自无冤。","几时诏下归丹阙，还领千官入閤门。"]},{"t":"寄陆浑县尉李景先","f":"五言律诗","c":["微俸还同请，唯君独自闲。","地偏无驿路，药贱管仙山。","月色生松里，泉声在石间。","吟诗复饮酒，何事更相关。"]},{"t":"寄周十七起居","f":"七言律诗","c":["鼕鼕九陌鼓声齐，百辟朝天马乱嘶。","月照浓霜寒更远，风吹红烛举还低。","官清立在金炉北，仗下归眠玉殿西。","莫笑老人多独出，晴山荒景觅诗题。"]},{"t":"寄国子杨巨源祭酒","f":"五言律诗","c":["日日新诗出，城中写不禁。","清高疑对竹，闲雅胜闻琴。","门户饶秋景，儿童解冷吟。","云山今作主，还借外人寻。"]},{"t":"寄郁上人","f":"五言律诗","c":["此生修道浅，愁见未来身。","谁为传真谛，唯应是上人。","自悲年已长，渐觉事难亲。","不向禅门去，他门无了因。"]},{"t":"寄陕州王司马","f":"七言律诗","c":["家寄秦城非本心，偶然头上有朝簪。","自当台直无因醉，一别诗宗更懒吟。","世事每将愁见扰，年光唯与老相侵。","欲知居处堪长久，须向山中学煮金。"]},{"t":"寄晖上人","f":"五言律诗","c":["日出月复没，悠悠昏与明。","修持经几劫，清净到今生。","林下知无相，人间苦是情。","终期逐师去，不拟老尘缨。"]},{"t":"寄贾岛","f":"五言律诗","c":["漫向城中住，儿童不识钱。","瓮头寒绝酒，灶额晓无烟。","狂发吟如哭，愁来坐似禅。","新诗有几首，旋被世人传。"]},{"t":"寄贾岛","f":"五言律诗","c":["寂寞荒原下，南山祗隔篱。","家贫唯我并，诗好复谁知。","草色无穷处，虫声少尽时。","朝昏鼓不到，闲卧益相宜。"]},{"t":"寄贾岛","f":"五言律诗","c":["疏拙祗如此，此身谁与同。","高情向酒上，无事在山中。","渐老病难理，久贫吟益空。","赖君时访宿，不避北斋风。"]},{"t":"寄贾岛时任普州司仓","f":"五言律诗","c":["长沙事可悲，普掾罪谁知。","千载人空尽，一家冤不移。","吟寒应齿落，才峭自名垂。","地远山重叠，难传相忆词。"]},{"t":"寄崔之仁山人","f":"七言律诗","c":["不得之仁消息久，秋来体色复何如。","苦将杯酒判身病，狂作文章信手书。","官职卑微从客笑，性灵闲野向钱疏。","几时身计浑无事，拣取深山一处居。"]},{"t":"寄崔之仁山人","f":"五言律诗","c":["百门坡上住，石屋两三间。","日月难教老，妻儿乞与闲。","仙经拣客问，药债煮金还。","何计能相访，终身得在山。"]},{"t":"寄紫阁无名头陀","f":"五言律诗","c":["峭行得如如，谁分圣与愚。","不眠知梦妄，无号免人呼。","山海禅皆遍，华夷佛岂殊。","何因接师话，清净在斯须。"]},{"t":"寄紫阁隐者","f":"五言律诗","c":["自闻憔客说，无计得相寻。","几世传高卧，全家在一林。","养情书览苦，采药路多深。","愿得为邻里，谁能说此心。"]},{"t":"寄嵩岳程光范","f":"五言律诗","c":["相别何容易，相逢便岁年。","客来嫌路远，谁得到君边。","岳色鸟啼里，钟声竹影前。","只应访支遁，时得话诗篇。"]},{"t":"寄鄠县尉李廓少府","f":"五言律诗","c":["岁满休为吏，吟诗著白衣。","爱山闲卧久，在世此心稀。","听鹤向风立，捕鱼乘月归。","比君才不及，谬得侍彤闱。"]},{"t":"寄题纵上人院","f":"五言律诗","c":["营营是与非，前乐后还悲。","今世已如此，他生愿似师。","禅房空旦暮，画壁半陈隋。","绕径苍苔迹，幽人来是谁。"]},{"t":"寄题蔡州蒋亭兼简田使君","f":"五言律诗","c":["几岁乱军里，蒋亭名不销。","无人知旧径，有药长新苗。","树宿山禽静，池通野水遥。","何因同此醉，永望思萧条。"]},{"t":"寄默然上人","f":"五言律诗","c":["晨餐夜复眠，日与月相连。","天下谁无病，人间乐是禅。","几生通佛性，一室但香烟。","结得无为社，还应有宿缘。"]},{"t":"惜别","f":"七言律诗","c":["酒阑歌罢更迟留，携手思量凭翠楼。","桃李容华犹叹月，风流才器亦悲秋。","光阴不觉朝昏过，岐路无穷早晚休。","似把剪刀裁别恨，两人分得一般愁。"]},{"t":"欲别","f":"七言律诗","c":["山川重叠远茫茫，欲别先忧别恨长。","红芍药花虽共醉，绿蘼芜影又分将。","鸳鸯有路高低去，鸿雁南飞一两行。","惆怅与君烟景迥，不知何日到潇湘。"]},{"t":"喜马戴冬夜见过期无可上人不至 其一","f":"五言律诗","c":["客来初夜里，药酒自开封。","老渐多归思，贫惟长病容。","苦寒灯焰细，近晓鼓声重。","僧可还相舍，深居闭古松。"]},{"t":"喜览泾州卢侍御诗卷","f":"五言律诗","c":["新诗十九首，丽格出青冥。","得处神应骇，成时力尽停。","正愁闻更喜，沈醉见还醒。","自是天才健，非关笔砚灵。"]},{"t":"喜览裴中丞诗卷","f":"五言律诗","c":["新诗盈道路，清韵似敲金。","调格江山峻，功夫日月深。","蜀笺方入写，越客始消吟。","后辈难知处，朝朝枉用心。"]},{"t":"喜贾岛至","f":"五言律诗","c":["布囊悬蹇驴，千里到贫居。","饮酒谁堪伴，留诗自与书。","爱眠知不醉，省语似相疏。","军吏衣裳窄，还应暗笑余。"]},{"t":"喜贾岛雨中访宿","f":"五言律诗","c":["雨里难逢客，闲吟不复眠。","虫声秋并起，林色夜相连。","爱酒此生里，趋朝未老前。","终须携手去，沧海棹鱼船。"]},{"t":"喜喻凫至","f":"五言律诗","c":["欲出心还懒，闲吟绕寝床。","道书虫食尽，酒律客偷将。","愁至为多病，贫来减得狂。","见君何所似，如热得清凉。"]},{"t":"喜雍陶秋夜访宿","f":"五言律诗","c":["晓立侍炉烟，夜归蓬荜眠。","露华明菊上，萤影灭灯前。","清漏和砧叠，栖禽与叶连。","高人来此宿，为似在山颠。"]},{"t":"敬宗皇帝挽词三首 其一","f":"五言律诗","c":["从谏停东幸，垂衣宝历昌。","汉昭登位少，周代卜年长。","綵仗三清路，麻衣万国丧。","玄宫今一闭，终古柏苍苍。"]},{"t":"敬宗皇帝挽词三首 其二","f":"五言律诗","c":["晚色启重扉，旌旗路渐移。","荆山鼎成日，湘浦竹斑时。","臣子终身感，山园七月期。","金茎看尚在，承露复何为。"]},{"t":"敬宗皇帝挽词三首 其三","f":"五言律诗","c":["紫陌起仙飙，川原共寂寥。","灵輴万国护，仪殿百神朝。","漏滴秋风路，笳吟灞水桥。","微臣空感咽，踊绝觉天遥。"]},{"t":"游阳河岸","f":"五言律诗","c":["终日游山困，今朝始傍河。","寻芳愁路尽，逢景畏人多。","鸟语催沽酒，鱼来似听歌。","醉时眠石上，肢体自婆娑。"]},{"t":"游杏溪兰若","f":"五言律诗","c":["踏得度溪湾，晨游暮不还。","月明松影路，春满杏花山。","戏狖跳林末，高僧住石间。","未肯离腰组，来此复何颜。"]},{"t":"游河桥晓望","f":"五言律诗","c":["闲上津桥立，天涯一望间。","秋风波上岸，旭日气连山。","偶圣今方变，朝宗岂复还。","昆崙在蕃界，作将亦何颜。"]},{"t":"游春十二首 其一","f":"五言律诗","c":["正月一日后，寻春更不眠。","自知还近僻，众说过于颠。","看水宁依路，登山欲到天。","悠悠芳思起，多是晚风前。"]},{"t":"游春十二首 其二","f":"五言律诗","c":["官卑长少事，县僻又无城。","未晓冲寒起，迎春忍病行。","树枝风掉软，菜甲土浮轻。","好个林间鹊，今朝足喜声。"]},{"t":"游春十二首 其三","f":"五言律诗","c":["诗酒相牵引，朝朝思不穷。","苔痕雪水里，春色竹烟中。","迎雨缘池草，摧花倚树风。","书非名利事，爱此少人同。"]},{"t":"游春十二首 其四","f":"五言律诗","c":["尘中主印吏，谁遣有高情。","趁煖檐前坐，寻芳树底行。","土融凝墅色，冰败满池声。","渐觉春相泥，朝来睡不轻。"]},{"t":"游春十二首 其五","f":"五言律诗","c":["疏顽无异事，随例但添年。","旧历藏深箧，新衣薄絮绵。","暖风浑酒色，晴日畅琴弦。","同伴无辞困，游春贵在先。"]},{"t":"游春十二首 其六","f":"五言律诗","c":["看春长不足，岂更觉身劳。","寺里花枝净，山中水色高。","嫩云轻似絮，新草细如毛。","并起诗人思，还应费笔毫。"]},{"t":"游春十二首 其七","f":"五言律诗","c":["悠悠小县吏，憔悴入新年。","远思遭诗恼，闲情被酒牵。","恋花林下饮，爱草野中眠。","疏懒今成性，谁人肯更怜。"]},{"t":"游春十二首 其八","f":"五言律诗","c":["处处春光遍，游人亦不稀。","向阳倾冷酒，看影试新衣。","嫩树行移长，幽禽语旋飞。","同来皆去尽，冲夜独吟归。"]},{"t":"游春十二首 其九","f":"五言律诗","c":["朝朝看春色，春色似相怜。","酒醒莺啼里，诗成蝶舞前。","摘花盈手露，折竹满庭烟。","亲故多相笑，疏狂似少年。"]},{"t":"游春十二首 其十","f":"五言律诗","c":["卑官还不恶，行止得逍遥。","晴野花侵路，春陂水上桥。","尘埃生暖色，药草长新苗。","看却烟光散，狂风处处飘。"]},{"t":"游春十二首 其十一","f":"五言律诗","c":["身被春光引，经时更不归。","嚼花香满口，书竹粉黏衣。","弄日莺狂语，迎风蝶倒飞。","自知疏懒性，得事亦应稀。"]},{"t":"游春十二首 其十二","f":"五言律诗","c":["晓脱青衫出，闲行气味长。","一瓶春酒色，数顷野花香。","朝客闻应羡，山僧见亦狂。","不将僮仆去，恐为损风光。"]},{"t":"游谢公亭","f":"五言律诗","c":["行行方避梦，又到谢亭来。","举世皆如此，伊余何处回？","竹鲜多透石，泉洁亦无苔。","坐与僧同语，谁能顾酒杯。"]},{"t":"答孟侍御早朝见寄","f":"五言律诗","c":["河倾月向西，九陌鼓声齐。","尘静霜华远，烟生曙色低。","禁门人已度，宫树鸟犹栖。","疏懒劳相问，登山有旧梯。"]},{"t":"腊日猎","f":"七言律诗","c":["健夫结束执旌旗，晓度长江自合围。","野外狐狸搜得尽，天边鸿雁射来稀。","苍鹰落日饥唯急，白马平川走似飞。","蜡节畋游非为己，莫惊刺史夜深归。"]},{"t":"谢汾州田大夫寄茸毡葡萄","f":"五言律诗","c":["筐封紫葡萄，筒卷白茸毛。","卧煖身应健，含消齿免劳。","衾衣疏不称，梨栗鄙难高。","晓起题诗报，寒澌满笔毫。"]},{"t":"谢秦校书与无可上人见访","f":"五言律诗","c":["道同无宿约，三伏自从容。","窗豁山侵座，扇摇风下松。","客吟多绕竹，僧饭只凭钟。","向晚分归路，莓苔行迹重。"]},{"t":"赏春","f":"七言律诗","c":["闲人祗是爱春光，迎得春来喜欲狂。","买酒怕迟教走马，看花嫌远自移床。","娇莺语足方离树，戏蝶飞高始过墙。","颠倒醉眠三数日，人间百事不思量。"]},{"t":"塞下曲","f":"五言律诗","c":["碛露黄云下，凝寒鼓不鸣。","战须移死地，军讳杀降兵。","印马秋遮虏，蒸沙夜筑城。","旧乡归不得，都尉负功名。"]},{"t":"酬万年张郎中见寄","f":"五言律诗","c":["贡籍常同府，周行今一时。","谏曹诚已忝，京邑岂相宜。","黑发年来尽，沧江归去迟。","何时得携手，林下静吟诗。"]},{"t":"酬卢汀谏议","f":"七言律诗","c":["粟如流水帛如山，依念仓边语笑间。","篇什纵横文案少，亲朋撩乱吏人闲。","杯觞引满从衣湿，墙壁书多任手顽。","遥贺来年二三月，綵衣先辈过春关。"]},{"t":"酬田卿书斋即事见寄","f":"五言律诗","c":["幽斋琴思静，晚下紫宸朝。","旧隐同溪远，周行隔品遥。","深槐蝉唧唧，疏竹雨萧萧。","不是相寻懒，烦君举酒瓢。"]},{"t":"酬田就","f":"五言律诗","c":["闲居多僻静，犹恐道相违。","只是夜深坐，那堪春未归。","嫩苔黏野色，香絮扑人衣。","纵有野僧到，终朝不话非。"]},{"t":"酬礼部李员外见寄","f":"七言律诗","c":["本求仙郡是闲居，岂向郎官更有书。","溪石谁思玉匠爱，烟鸿愿与弋人疏。","自来江上眠方稳，旧在城中病悉除。","唯见君诗难便舍，寒宵吟到晓更初。"]},{"t":"酬光禄田卿末伏见寄","f":"五言律诗","c":["下伏秋期近，还知扇渐疏。","惊飙坠邻果，暴雨落江鱼。","贵寺虽同秩，闲曹只管书。","朝朝廊下食，相庇在肴菹。"]},{"t":"酬张籍司业见寄","f":"五言律诗","c":["日日在心中，青山青桂丛。","高人多爱静，归路亦应同。","罢吏方无病，因僧得解空。","新诗劳见问，吟对竹林风。"]},{"t":"酬李廓精舍南台望月见寄","f":"五言律诗","c":["看月空门里，诗家境有馀。","露寒僧梵出，林静鸟巢疏。","远色当秋半，清光胜夜初。","独无台上思，寂寞守吾庐。"]},{"t":"酬薛奉礼见赠之作","f":"七言律诗","c":["栖栖沧海一耕人，诏遣江边作使君。","山顶雨馀青到地，涛头风起白连云。","诗成客见书墙和，药熟僧来就鼎分。","珍重来章相借分，芳名未识已曾闻。"]},{"t":"暮春书事","f":"五言律诗","c":["穷巷少芳菲，苍苔一径微。","酒醒闻客别，年长送春归。","宿愿眠云峤，浮名系锁闱。","未因丞相庇，难得脱朝衣。"]},{"t":"霁后登楼","f":"五言律诗","c":["高楼初霁后，远望思无穷。","雨洗青山净，春蒸大野融。","碧池舒煖景，若柳亸和风。","为有登临兴，独吟落照中。"]},{"t":"题大理崔少卿驸马林亭","f":"五言律诗","c":["每来归意懒，都尉似山人。","台榭栖双鹭，松篁隔四邻。","迸泉清胜雨，深洞暖如春。","更看题诗处，前轩粉壁新。"]},{"t":"题厉玄侍御所居","f":"五言律诗","c":["幽栖一亩宫，清峭似山峰。","邻里不通径，俸钱唯买松。","野人时寄宿，谷鸟自相逢。","朝路床前是，谁知晓起慵。"]},{"t":"题田将军宅","f":"七言律诗","c":["焚香书院最风流，莎草缘墙绿藓秋。","近砌别穿浇药井，临街新起看山楼。","栖禽恋竹明犹在，闲客观花夜未休。","好是暗移城里宅，清凉浑得似江头。"]},{"t":"题刑部马员外修行里南街新居","f":"五言律诗","c":["帝里谁无宅，青山秖属君。","闲窗连竹色，幽砌上苔文。","远近高低树，东西南北云。","朝朝常独见，免被四邻分。"]},{"t":"题贞女祠","f":"五言律诗","c":["此女骨为土，贞名不可移。","精灵閟何处，蘋藻奠空祠。","水石生异状，杉松无病枝。","我来方谢雨，延滞失归期。"]},{"t":"题李频新居","f":"五言律诗","c":["赁居求贱处，深僻任人嫌。","盖地花如绣，当门竹胜帘。","劝僧尝药酒，教仆辨书签。","庭际山宜小，休令著石添。"]},{"t":"题杭州南亭","f":"五言律诗","c":["旧隐即云林，思归日日深。","如今来此地，无复有前心。","古石生灵草，长松栖异禽。","暮潮檐下过，溅浪湿衣襟。"]},{"t":"题郭侍郎亲仁里幽居","f":"五言律诗","c":["入门尘外思，苔径药苗间。","洞里应生玉，庭前自有山。","帝城唯此静，朝客更谁闲。","野鹤松中语，时时去复还。"]},{"t":"题僧院引泉","f":"五言律诗","c":["泉眼高千尺，山僧取得归。","架空横竹引，凿石透渠飞。","洗药溪流浊，浇花雨力微。","朝昏长绕看，护惜似持衣。"]},{"t":"赠少室山麻襦僧","f":"五言律诗","c":["秖辫麻为衲，此中经几春。","庵前多猛兽，径小绝行人。","泉近濆瓶履，山深少垢尘。","想师正法指，喻我独迷津。"]},{"t":"赠王山人","f":"五言律诗","c":["贤哲论独诞，吾宗次定今。","诗吟天地广，觉印果因深。","教演归恭敬，名标中外钦。","既能施六度，了悟达双林。"]},{"t":"赠王建司马","f":"五言律诗","c":["久向空门隐，交亲亦不知。","文高轻古意，官冷似前资。","老觉僧斋健，贫还酒债迟。","仙方小字写，行坐把相随。"]},{"t":"赠王尊师","f":"七言律诗","c":["先生自说瀛洲路，多在青松白石间。","海岸夜中常见日，仙宫深处却无山。","犬随鹤去游诸洞，龙作人来问大还。","今日偶闻尘外事，朝簪未掷复何颜。"]},{"t":"赠任士曹","f":"五言律诗","c":["宪皇十一祀，共得春闱书。","道直淹曹掾，命通侍玉除。","浮生年月促，九陌笑言疏。","何计同归去，沧江有弊庐。"]},{"t":"赠刘叉","f":"五言律诗","c":["自君离海上，垂钓更何人。","独宿空堂雨，闲行九陌尘。","避时曾变姓，救难似嫌身。","何处相期宿，咸阳酒市春。"]},{"t":"赠张质山人","f":"五言律诗","c":["先生居处僻，荆棘与墙齐。","酒好宁论价，诗狂不著题。","烧成度世药，踏尽上山梯。","懒听闲人语，争如谷鸟啼。"]},{"t":"赠供奉僧次融","f":"五言律诗","c":["会解如来意，僧家独有君。","开经对天子，骑马过声闻。","本寺远于日，新诗高似云。","热时吟一句，凉冷胜秋分。"]},{"t":"赠常州院僧","f":"五言律诗","c":["一住毗陵寺，师应祗信缘。","院贫人施食，窗静鸟窥禅。","古磬声难尽，秋灯色更鲜。","仍闻开讲日，湖上少鱼船。"]},{"t":"赠僧绍明","f":"五言律诗","c":["西方清净路，此路出何门。","见说师知处，从来佛不言。","今生多病恼，自晓至黄昏。","唯寐方无事，那堪梦亦喧。"]},{"t":"及第后夜中书事","f":"五言古诗","c":["夜睡常惊起，春光属野夫。","新衔添一字，旧友逊前途。","喜过还疑梦，狂来不似儒。","爱花持烛看，忆酒犯街沽。","天上名应定，人间盛更无。","报恩丞相閤，何啻杀微躯。"]},{"t":"中秋夜洞庭圆月","f":"五言古诗","c":["素月闲秋景，骚人汎洞庭。","沧波正澄霁，凉叶未飘零。","练彩凝葭菼，霜容静杳冥。","晓栖河畔鹤，宵映渚边萤。","圆彩含珠魄，微飙发桂馨。","谁怜采蘋客，此夜宿孤汀。"]},{"t":"书怀寄友人","f":"五言古诗","c":["精心奉北宗，微宦在南宫。","举世劳为适，开门事不穷。","年来复几日，蝉去又鸣鸿。","衰疾谁人问，闲情与酒通。","四邻寒稍静，九陌夜方空。","知老何山是，思归愚谷中。"]},{"t":"心怀霜","f":"五言古诗","c":["欲识为诗苦，秋霜若在心。","神清方耿耿，气肃觉沈沈。","皓素中方委，严凝得更深。","依稀轻夕渚，髣髴在寒林。","思劲凄孤韵，声酸激冷吟。","还如饮冰士，励节望知音。"]},{"t":"西掖寓直春晓闻残漏","f":"五言古诗","c":["直庐仙掖近，春气曙犹寒。","隐隐银河在，丁丁玉漏残。","微风飘更切，万籁杂应难。","凤阁明初启，鸡人唱渐阑。","静宜来禁里，清是下云端。","我识朝天路，从容自整冠。"]},{"t":"和门下李相饯西蜀相公","f":"五言古诗","c":["圣朝同舜日，作相有夔龙。","理化知无外，烝黎尽可封。","燮和皆达识，出入并登庸。","武骑增馀勇，儒冠贵所从。","赠诗全六义，出镇越千峰。","连日陈天乐，芳筵叠酒钟。","乌台情已洽，凤阁分弥浓。","栈转旌摇水，崖高马蹋松。","恩深施远俗，化美见前踪。","江晓流巴字，山晴耸剑峰。","双油拥上宰，四海羡临邛。","先路声华远，离京诏旨重。","岁除今向尽，春色即相逢。","嫩叶抽赪蕊，新苔长翠茸。","冰销鱼潎潎，林煖鸟噰噰。","泉落闻难尽，花开看不供。","青城方眷恋，黄阁竟从容。","计日归台席，还听长乐钟。"]},{"t":"和太仆田卿酬殷尧藩侍御见寄","f":"五言古诗","c":["往还知分熟，酬赠思同新。","嗜饮殷偏逸，闲吟卿亦贫。","古苔寒更翠，修竹静无邻。","促席灯浮酒，听鸿霜满身。","浅才唯是我，高论更何人。","携手宜相访，穷行少路尘。"]},{"t":"和王郎中召看牡丹","f":"五言古诗","c":["葩叠萼相重，烧栏复照空。","妍姿朝景里，醉艳晚烟中。","乍怪霞临砌，还疑烛出笼。","绕行惊地赤，移坐觉衣红。","殷丽开繁朵，香浓发几丛。","裁绡样岂似，染茜色宁同。","嫩畏人看损，鲜愁日炙融。","婵娟涵宿露，烂熳抵春风。","纵赏襟情合，闲吟景思通。","客来归尽懒，莺恋语无穷。","万物珍那比，千金买不充。","如今难更有，纵有在仙宫。"]},{"t":"和李十二舍人裴四二舍人两阁老酬白少傅见寄","f":"七言古诗","c":["罢草王言星岁久，嵩高山色日相亲。","萧条雨夜吟连晓，撩乱花时看尽春。","此世逍遥应独得，古来闲散有谁邻。","林中长老呼居士，天下书生仰达人。","酒挈数瓶杯亦阔，诗成千首语皆新。","纶闱并命诚宜贺，不念衰年寄上频。"]},{"t":"和李补阙曲江看莲花","f":"五言古诗","c":["露荷迎曙发，灼灼复田田。","乍见神应骇，频来眼尚颠。","光凝珠有蒂，焰起火无烟。","粉腻黄丝蕊，心重碧玉钱。","日浮秋转丽，雨洒晚弥鲜。","醉艳酣千朵，愁红思一川。","绿茎扶萼正，翠菂满房圆。","淡晕还殊众，繁英得自然。","高名犹不厌，上客去争先。","景逸倾芳酒，怀浓习綵笺。","海霞宁有态，蜀锦不成妍。","客至应消病，僧来欲破禅。","晓多临水立，夜只傍堤眠。","金似明沙渚，灯疑宿浦船。","风惊丛乍密，鱼戏影微偏。","秾彩烧晴雾，殷姿缬碧泉。","画工投粉笔，宫女弃花钿。","鸟恋惊难起，蜂偷困不前。","绕行香烂熳，折赠意缠绵。","谁计江南曲，风流合管弦。"]},{"t":"和李舍人秋日卧疾言怀","f":"五言古诗","c":["闲卧襟情远，西风菊渐芳。","虚窗通晓景，珍簟卷秋光。","果坠青莎径，尘离绿藓墙。","药奁开静室，书阁出丛篁。","对酒吟难尽，思山梦稍长。","王言生彩笔，朝服惹炉香。","松影幽连砌，虫声冷到床。","诗成谁敢和，清思若怀霜。"]},{"t":"和郑相演杨尚书蜀中唱和诗","f":"五言古诗","c":["天福坤维厚，忠贤拥节旄。","江同渭滨远，山似傅岩高。","元气符才格，文星照笔毫。","五言全丽则，六义出风骚。","圣日麻双下，洪炉柄共操。","宠荣连雨露，先后比萧曹。","唱绝时难和，吟多客讵劳。","四方虽纸贵，谁怕费钱刀。"]},{"t":"和座主相公西亭秋日即事","f":"五言古诗","c":["西亭秋望好，宁要更垂帘。","夫子墙还峻，酂侯宅过谦。","微风红叶下，新雨绿苔黏。","窗外松初长，栏中药旋添。","海图装玉轴，书目记牙签。","竹色晴连地，山光远入檐。","酒浓杯稍重，诗冷语多尖。","属和才虽浅，题高免客嫌。"]},{"t":"和座主相公雨中作","f":"五言古诗","c":["清气润华屋，东风吹雨匀。","花低惊艳重，竹净觉声真。","山际凝如雾，云中散似尘。","萧萧下碧落，点点救生民。","缓洒雷霆细，微沾瓦砾新。","诗成难继和，造化笔通神。"]},{"t":"和裴令公游南庄忆白二十韦七二宾客","f":"五言古诗","c":["四郊初雨歇，高树滴犹残。","池满红莲湿，云收绿野宽。","花开半山晓，竹动数村寒。","斗雀翻衣袂，惊鱼触钓竿。","樽前多野客，膝下尽郎官。","斸石通泉脉，移松出药栏。","关东分务重，天下似公难。","半醉思韦白，题诗染彩翰。"]},{"t":"和裴令公新成绿野堂即事","f":"五言古诗","c":["结搆立嘉名，轩窗四面明。","丘墙高莫比，萧宅僻还清。","池际龟潜戏，庭前药旋生。","树深檐稍邃，石峭径难平。","道旷襟情远，神闲视听精。","古今功独出，大小隐俱成。","曙雨新苔色，秋风长桂声。","携诗就竹写，取酒对花倾。","古寺招僧饭，方塘看鹤行。","人间无此贵，半仗暮归城。"]},{"t":"和裴结端公早朝","f":"五言古诗","c":["鱼钥千门启，鸡人唱晓传。","冕旒临玉殿，丞相入炉烟。","列位同居左，分行忝在前。","仰闻天语近，俯拜佩声连。","綵杖祥光动，彤庭霁色鲜。","威仪谁可纪，柱史有新篇。"]},{"t":"奉和门下相公雨中寄裴给事","f":"五言古诗","c":["晓起闲看雨，垂檐自滴阶。","风清想林壑，云湿似江淮。","石信浮沤重，泥从积藓埋。","气消浓酒力，心助独吟怀。","飒飒通琴韵，萧萧静竹斋。","綵毫无限思，念与夕郎乖。"]},{"t":"奉和四松","f":"五言古诗","c":["四松相对植，苍翠映中台。","擢干凌空去，移根斸石开。","阴阳气潜煦，造化手亲栽。","日月滋佳色，烟霄长异材。","清音胜在涧，寒影遍生苔。","静绕霜沾履，闲看酒满杯。","同荣朱户际，永日白云隈。","密叶闻风度，高枝见鹤来。","赏心难可尽，丽什妙难裁。","此地无因到，循环几百回。"]},{"t":"杭州观潮","f":"五言古诗","c":["楼有章亭号，涛来自古今。","势连苍海阔，色比白云深。","怒雪驱寒气，狂雷散大音。","浪高风更起，波急石难沈。","鸟惧多遥过，龙惊不敢吟。","坳如开玉穴，危似走琼岑。","但褫千人魄，那知伍相心。","岸摧连古道，洲涨碚丛林。","跳沫山皆湿，当江日半阴。","天然与禹凿，此理遣谁寻。"]},{"t":"金州书事寄山中旧友","f":"五言古诗","c":["安康虽好郡，刺史是憨翁。","买酒终朝饮，吟诗一室空。","自知为政拙，众亦觉心公。","亲事星河在，忧人骨肉同。","簿书岚色里，鼓角水声中。","井邑神州接，帆樯海路通。","野亭晴带雾，竹寺夏多风。","溉稻长洲白，烧林远岫红。","旧山期已失，芳草思何穷。","林下无相笑，男儿五马雄。"]},{"t":"省直书事","f":"五言古诗","c":["默默沧江老，官分右掖荣。","立朝班近殿，奏直上知名。","晓雾和香气，晴楼下乐声。","蜀笺金屑腻，月兔笔毫精。","禁树霏烟覆，宫墙瑞草生。","露盘秋更出，玉漏昼还清。","碧藓无尘染，寒蝉似鸟鸣。","竹深云自宿，天近日先明。","孱懦难封诏，疏愚但掷觥。","素餐终日足，宁免众人轻。"]},{"t":"送杜立归蜀","f":"五言古诗","c":["迢递三千里，西南是去程。","杜陵家已尽，蜀国客重行。","雪照巴江色，风吹栈阁声。","马嘶山稍煖，人语店初明。","旅梦心多感，孤吟气不平。","谁为李白后，为访锦官城。"]},{"t":"送杨尚书祭西岳","f":"五言古诗","c":["报功严祀典，宠诏下明庭。","酒气飘林岭，香烟入杳冥。","乐清三奏备，词直百神听。","衣拂云霞湿，诗通水石灵。","何因逐驺骑，暂得到岩扃。"]},{"t":"送狄尚书镇太原","f":"五言古诗","c":["授钺儒生贵，倾朝赴饯筵。","麾幢官在省，礼乐将临边。","代马龙相杂，汾河海暗连。","远戎移帐幕，高鸟避旌旃。","天下屯兵处，皇威破虏年。","防秋嫌垒近，入塞必身先。","中外恩重叠，科名岁接连。","散材无所用，老向琐闱眠。"]},{"t":"送陆畅侍御归扬州","f":"五言古诗","c":["故园偏接近，霅水洞庭边。","归去知何日，相逢各长年。","山川南北路，风雪别离天。","楚色穷冬烧，淮声独夜船。","从军丞相府，谈笑酒杯前。"]},{"t":"送家兄赴任昭义","f":"五言古诗","c":["早得白眉名，之官濠上城。","别离浮世事，迢遰长年情。","广陌垂花影，遥林起雨声。","出关春草长，过汴夏云生。","黠吏先潜去，疲人相次迎。","宴馀和酒拜，魂梦共东行。"]},{"t":"送崔玄亮赴果州冬夜宴韩卿宅","f":"五言古诗","c":["兰烛照重茵，飞杯复几分。","主人寒不寐，上客晓离群。","骑吏缘青壁，旌旗度白云。","剑铭生藓色，巴字叠冰文。","华省思仙侣，疲民爱使君。","泠泠唯自适，郡邸有谁闻。"]},{"t":"送韩湘赴江西从事","f":"五言古诗","c":["年少登科客，从军诏命新。","行装有兵器，祖席尽诗人。","细雨湘城暮，微风楚水春。","浔阳应足雁，梦泽岂无尘。","猿叫来山顶，潮痕在树身。","从容多暇日，佳句寄须频。"]},{"t":"送裴大夫赴亳州","f":"五言古诗","c":["杭人遮道路，垂泣浙江前。","谯国迎舟舰，行歌汴水边。","周旋君量远，交代我才偏。","寒日严旌戟，晴风出管弦。","一杯诚淡薄，四坐愿留连。","异政承殊泽，应为天下先。"]},{"t":"寄九华费冠卿","f":"五言古诗","c":["逍遥罾缴外，高鸟与潜鱼。","阙下无朝籍，林间有诏书。","夜眠青玉洞，晓饭白云蔬。","四海人空老，九华君独居。","此心谁复识，日与世情疏。"]},{"t":"寄王度居士","f":"五言古诗","c":["憔悴王居士，颠狂不称时。","天公与贫病，时辈复轻欺。","茅屋随年借，盘餐逐日移。","弃嫌官似梦，珍重酒如师。","无竹栽芦看，思山叠石为。","静窗留客话，古寺觅僧棋。","瘦马寒来死，羸童饿得痴。","唯应寻阮籍，心事远相知。"]},{"t":"寄华州李中丞","f":"五言古诗","c":["毛女峰前郡，烟霞气转清。","庭分灵掌影，窗度瀑泉声。","藓径人稀到，松斋药自生。","常餐亦芝朮，闲客是公卿。","看水逢仙鹤，登楼见帝城。","养生非酒病，难隐是诗名。","省署尝连步，江皋欲独耕。","偶题无六义，聊以达微诚。"]},{"t":"寄李群玉","f":"五言古诗","c":["九衢名与利，无计扰闲人。","道远期轻世，才高贵重身。","石脂稀胜乳，玉粉细于尘。","骨换肌肤腻，心灵气色真。","嵩山高到日，洛水煖如春。","居住应安稳，黄金几灶新。"]},{"t":"寄杨工部闻毗陵舍弟自罨溪入茶山","f":"五言古诗","c":["采茶溪路好，花影半浮沈。","画舸僧同上，春山客共寻。","芳新生石际，幽嫩在山阴。","色是春光染，香惊日气侵。","试尝应酒醒，封进定恩深。","芳贻千里外，怡怡太府吟。"]},{"t":"寄绛州李使君","f":"五言古诗","c":["独施清静化，千里管横汾。","黎庶应深感，朝庭亦细闻。","心期在黄老，家事是功勋。","物外须仙侣，人间要使君。","花多匀地落，山近满厅云。","戎客无因去，西看白日曛。"]},{"t":"寄送卢拱秘书游魏州","f":"五言古诗","c":["太行山下路，荆棘昨来平。","一自开元后，今逢上客行。","地形吞北虏，人事接东京。","埽洒氛埃静，游从气概生。","蓟门春不艳，淇水煖还清。","看野风情远，寻花酒病成。","官闲身自在，诗逸语纵横。","车马回应晚，烟光满去程。"]},{"t":"寄题尉迟少卿郊居","f":"五言古诗","c":["卿仕在关东，林居思不穷。","朝衣挂壁上，厩马放田中。","隅坐唯禅子，随行只药童。","砌莎留宿露，庭竹出清风。","浓翠生苔点，辛香发桂丛。","莲池伊水入，石径远山通。","愚者心还静，高人迹自同。","无能相近住，终日羡邻翁。"]},{"t":"游昊天玄都观","f":"五言古诗","c":["性同相见易，紫府共闲行。","阴径红桃落，秋坛白石生。","藓文连竹色，鹤语应松声。","风定药香细，树声泉气清。","垂檐灵草影，绕壁古山名。","围外坊无禁，归时踏月明。"]},{"t":"赋月华临静夜","f":"古风","c":["长空埃?灭，皎皎月华临。","色正秋将半，光鲜夜自深。","九霄晴更彻，四野气难侵。","静照遥山出，孤明列宿沈。","高人应不寐，惊鹊复何心。","漏尽东方晓，佳期何处寻。"]},{"t":"酬任畴协律夏中苦雨见寄","f":"五言古诗","c":["银汉波澜溢，经旬雨未休。","细听宜隔牖，远望忆高楼。","风急飘还断，云低落更稠。","走童惊掣电，饥鸟啄浮沤。","丝网张空际，蛛绳续瓦沟。","青蛙多入户，潢潦欲胜舟。","雷怒疑山破，池浑似土流。","灰人漫禳厌，水马恣沈浮。","广陌应翻浪，贫居恐作湫。","阳精藏不耀，阴气盛难收。","远色重林暮，繁声四壁秋。","望晴思见日，防冷欲披裘。","枕润眠还懒，车羸出转忧。","散空烟漠漠，迸溜竹修修。","树暗蝉吟咽，巢倾燕语愁。","琴书凉簟净，灯烛夜窗幽。","天下那能向，龙边岂易求。","湿烟凝灶额，荒草覆墙头。","酒思凄方罢，诗情耿始抽。","下床先仗屐，汲井恐飘瓯。","危坐徒相忆，佳期未有由。","劳君寄新什，终日不能酬。"]},{"t":"酬光禄田卿六韵见寄","f":"五言古诗","c":["以病辞朝谒，迂疏种药翁。","心弥念鱼鸟，诏遣理兵戎。","绕户旌旗影，吹人鼓角风。","雪晴嵩岳顶，树老陕城宫。","莅职才微薄，归山路未通。","名卿诗句峭，诮我在关东。"]},{"t":"题山寺","f":"五言古诗","c":["千重山崦里，楼阁影参差。","未暇寻僧院，先看置寺碑。","竹深行渐暗，石稳坐多时。","古塔虫蛇善，阴廊鸟雀痴。","云开上界近，泉落下方迟。","为爱青桐叶，因题满树诗。"]},{"t":"题凤翔西郭新亭","f":"五言古诗","c":["西郭尘埃外，新亭制度奇。","地形当要处，人力是闲时。","结搆方殊绝，高低更合宜。","栋梁清俸买，松竹远山移。","佛寺幽难敌，仙家景可追。","良工惭巧尽，上客恨逢迟。","两面寒波涨，当前软柳垂。","清虚宜月入，凉冷胜风吹。","宴赏军容静，登临妓乐随。","鱼龙听弦管，凫鹤识旌旗。","泛鹢春流阔，飞觞白日欹。","闲花长在户，嫩藓乍缘墀。","永望情无极，频来困不辞。","云峰晴转翠，烟树晓逾滋。","向野惟贪静，临空遽觉危。","行人如不到，游乐更何为。"]},{"t":"题长安薛员外水阁","f":"五言古诗","c":["亭亭新阁成，风景益鲜明。","石尽太湖色，水多湘渚声。","翠筠和粉长，零露逐荷倾。","时倚高窗望，幽寻小径行。","林疏看鸟语，池近识鱼情。","政暇招闲客，唯将酒送迎。"]},{"t":"题河上亭","f":"五言古诗","c":["亭亭河上亭，鱼踯水禽鸣。","九曲何时尽，千峰今日清。","晨光秋更远，暑气夏常轻。","杯里移樯影，琴中有浪声。","岸莎连砌静，渔火入窗明。","来此多沈醉，神高无宿酲。"]},{"t":"题郑驸马林亭","f":"五言古诗","c":["东园连宅起，胜事与心期。","幽洞自生药，新篁迸入池。","密林行不尽，芳草坐难移。","石翠疑无质，莺歌似有词。","莎台高出树，藓壁净题诗。","我独多来赏，九衢人不知。"]},{"t":"题宣义池亭","f":"五言古诗","c":["春入池亭好，风光暖更鲜。","寻芳行不困，逐胜坐还迁。","细草乱如发，幽禽鸣似弦。","苔文翻古篆，石色学秋天。","花落能漂酒，萍开解避船。","暂来还愈疾，久住合成仙。","迸笋支阶起，垂藤压树偏。","此生应借看，自计买无钱。"]},{"t":"赠卢大夫将军","f":"五言古诗","c":["将军身在城，讵得虏尘清。","酿酒邀闲客，吟诗直禁营。","苍鹰春不下，战马夜空鸣。","碣石应无业，皇州独有名。","上山嫌䯗重，拔剑叹衣生。","公议今如此，登坛到即行。"]},{"t":"赠张籍太祝","f":"五言古诗","c":["绝妙江南曲，凄凉怨女诗。","古风无手敌，新语是人知。","飞动应由格，功夫过却奇。","麟台添集卷，乐府换歌词。","李白应先拜，刘祯必自疑。","贫须君子救，病合国家医。","野客开山借，邻僧与米炊。","甘贫辞聘币，依选受官资。","多见愁连晓，稀闻债尽时。","圣朝文物盛，太祝独低眉。"]},{"t":"从军行","f":"五言古诗","c":["滥得进士名，才用苦不长。","性癖艺亦独，十年作诗章。","六义虽粗成，名字犹未扬。","将军俯招引，遣脱儒衣裳。","常恐虚受恩，不惯把刀鎗。","又无远筹略，坐使虏灭亡。","昨来发兵师，各各赴战场。","顾我同老弱，不得随戎行。","丈夫生世间，职分贵所当。","从军不出门，岂异病在床。","谁不恋其家，其家无风霜。","鹰鹘念搏击，岂贵食满肠。"]},{"t":"买太湖石","f":"五言古诗","c":["我尝游太湖，爱石青嵯峨。","波澜取不得，自后长咨嗟。","奇哉卖石翁，不傍豪贵家。","负石听苦吟，虽贫亦来过。","贵我辨识精，取价复不多。","比之昔所见，珍怪颇更加。","背面淙注痕，孔隙若琢磨。","水称至柔物，湖乃生壮波。","或云此天生，嵌空亦非他。","气质偶不合，如地生江河。","置之书房前，晓雾常纷罗。","碧光入四邻，墙壁难蔽遮。","客来谓我宅，忽若岩之阿。"]},{"t":"庄居野行","f":"五言古诗","c":["客行野田间，此屋皆闭户。","借问屋中人，尽去作商贾。","官家不税商，税农服作苦。","居人尽东西，道路侵垄亩。","采玉上山颠，探珠入水府。","边兵索衣食，此物同泥土。","古来一人耕，三人食犹饥。","如今千万家，无一把锄犁。","我仓常空虚，我田生蒺藜。","上天不雨粟，何由活烝黎。"]},{"t":"过张邯郸庄","f":"五言古诗","c":["客行长似病，烦热束四肢。","到君读书堂，忽若逢良医。","堂前水交流，堂下树交枝。","两门延风凉，洗我昏浊肌。","与子还往熟，坐卧恣所宜。","时时相献酬，文字当酒卮。","野饭具藜藿，永日亦不饥。","苟餐非其所，鲙炙为蒺藜。","时清士人闲，耕作唯文词。","岂独乡里荐，当取四海知。"]},{"t":"杏溪十首 石潭","f":"五言古诗","c":["晓向潭上行，夕就潭边宿。","清冷无波澜，潎潎鱼相逐。","钓翁坐不起，见我往来熟。"]},{"t":"杏溪十首 石濑","f":"五言古诗","c":["散漫复潺湲，半砂半和石。","清风波亦无，历历鱼可搦。","我来亦屡久，归路常日夕。"]},{"t":"杏溪十首 杏水","f":"五言古诗","c":["不与江水接，自出林中央。","穿花复远水，一山闻杏香。","我来持茗瓯，日屡此来尝。"]},{"t":"杏溪十首 杏溪","f":"五言古诗","c":["桃花四散飞，桃子压枝垂。","寂寂青阴里，幽人举步迟。","慇勤念此径，我去复来谁。"]},{"t":"杏溪十首 枫林堰","f":"五言古诗","c":["森森枫树林，护此石门堰。","杏堤数里馀，枫影覆亦遍。","鸬鹚与钓童，质异同所愿。"]},{"t":"杏溪十首 架水藤","f":"五言古诗","c":["濛濛紫花藤，下复清溪水。","若遣随波流，不如风飘起。","风飘或近堤，随波千万里。"]},{"t":"杏溪十首 莲塘","f":"五言古诗","c":["方塘菡萏高，繁艳相照耀。","幽人夜眠起，忽疑野中烧。","晓寻不知休，白石岸亦峭。"]},{"t":"杏溪十首 望江峰","f":"五言古诗","c":["念昔有此峰，在彼江陵先。","举世未能知，愚亦望同贤。","我来心益闷，欲上天公笺。"]},{"t":"杏溪十首 渚上竹","f":"五言古诗","c":["叶叶新春筠，下复清浅流。","微风屡此来，决决复脩脩。","诗人月下吟，月堕吟不休。"]},{"t":"杏溪十首 溪路","f":"五言古诗","c":["此路何潇洒，永无公卿迹。","日日多往来，藜杖与桑屐。","路边何所有，磊磊青渌石。"]},{"t":"拾得古砚","f":"五言古诗","c":["僻性爱古物，终岁求不获。","昨朝得古砚，黄河滩之侧。","念此黄河中，应有昔人宅。","宅亦作流水，斯砚未变易。","波澜所激触，背面生罅隙。","质状朴且丑，今人作不得。","捧持且惊叹，不敢施笔墨。","或恐先圣人，尝用修六籍。","置之洁净室，一日三磨拭。","大喜豪贵嫌，久长得保惜。"]},{"t":"秋中寄崔道士","f":"五言古诗","c":["贫居雀喧噪，况乃静巷陌。","夜眠睡不成，空庭闻露滴。","旁有一杯酒，欢然如对客。","月光久逾明，照得笔墨白。","平生志舒豁，难可似兹夕。","四肢得自便，虽劳不为役。","故人山中住，善治活身策。","五谷口不尝，比僧更闲寂。","我今暂得安，自谓脱幽戚。","君身长逍遥，日月争老得。"]},{"t":"送王求","f":"五言古诗","c":["士有经世筹，自无活身策。","求食道路间，劳困甚徒役。","我身与子同，日被饥寒迫。","侧望卿相门，难入坚如石。","为农昧耕耘，作商迷贸易。","空把书卷行，投人买罪责。","六月南风多，苦旱土色赤。","坐家心尚焦，况乃远作客。","羸马出郭门，饯饮晓连夕。","愿君似醉肠，莫谩生忧戚。"]},{"t":"送任畹评事赴沂海","f":"五言古诗","c":["掷笔不作尉，戎衣从嫖姚。","严冬入都门，仆马气益豪。","沂州右镇雄，士勇旌旗高。","洛东无忧虞，半夜开虎牢。","丈夫贵功勋，不贵爵禄饶。","仰眠作书生，衣食何由销。","任生非常才，临事胆不摇。","必当展长画，逆波斩鲸鳌。","九陌尘土黑，话别立远郊。","孟坚勒燕然，岂独在汉朝。"]},{"t":"送张宗原","f":"五言古诗","c":["东门送客道，春色如死灰。","一客失意行，十客颜色低。","住者既无家，去者又非归。","穷愁一成疾，百药不可治。","子贤我且愚，命分不合齐。","谁开蹇踬门，日日同游栖。","子行何所之，切切食与衣。","谁能买仁义，令子无寒饥。","野田不生草，四向生路岐。","士人甚商贾，终日须东西。","鸿雁春北去，秋风复南飞。","勉君向前路，无失相见期。"]},{"t":"送李馀及第归蜀","f":"五言古诗","c":["蜀山高岧峣，蜀客无平才。","日饮锦江水，文章盈其怀。","十年作贡宾，九年多邅回。","春来登高科，升天得梯阶。","手持冬集书，还家献庭闱。","人生此为荣，得如君者稀。","李白蜀道难，羞为无成归。","子今称意行，所历安觉危。","与子久相从，今朝忽乖离。","风飘海中船，会合难自期。","长安米价高，伊我常渴饥。","临岐歌送子，无声但陈词。","义交外不亲，利交内相违。","勉子慎其道，急若食与衣。","苦爇道路赤，行人念前驰。","一杯不可轻，远别方自兹。"]},{"t":"送狄兼谟下第归故山","f":"五言古诗","c":["慈恩塔上名，昨日败垂成。","赁舍应无直，居山岂钓声。","半年犹小隐，数日得闲行。","映竹窥猿剧，寻云探鹤情。","爱花高酒户，煮药污茶铛。","莫便多时住，烟霄路在城。"]},{"t":"送敬法师归福州","f":"五言律诗","c":["结得随缘伴，蝉鸣方出关。","新经译旧寺，故国与谁还。","斋为无钟早，心因罢讲闲。","东南数千里，何处不逢山。"]},{"t":"恶神行雨","f":"古风","c":["凶神扇?恶神行，汹涌挨排白雾生。","风击水凹波扑凸，雨漴山口地嵌坑。","龙喷黑气翻腾滚，鬼掣红光劈划揁。","哮吼忽雷声揭石，满天啾唧闹轰轰。"]},{"t":"寄主客张郎中","f":"五言古诗","c":["年长方慕道，金丹事参差。","故园归未得，秋风思难持。","蹇拙公府弃，朴静高人知。","以我齐杖屦，昏旭讵相离。","吟诗红叶寺，对酒黄菊篱。","所赏未及毕，后游良有期。","粲粲华省步，屑屑旅客姿。","未同山中去，固当殊路岐。"]},{"t":"寄旧山隐者","f":"五言古诗","c":["别君须臾间，历日两度新。","念彼白日长，复值人事并。","未改当时居，心事如野云。","朝朝恣行坐，百事都不闻。","奈何道未尽，出山最艰辛。","奔走衢路间，四枝不属身。","名在进士场，笔毫争等伦。","我性本朴直，词理安得文。","纵然自称心，又不合众人。","以此名字低，不如风中尘。","昨逢卖药客，云是居山邻。","说君忆我心，憔悴其形神。","昔是同枝鸟，今作万里分。","万里亦未遥，喧静终难群。"]},{"t":"寄李馀卧疾","f":"五言古诗","c":["穷节弥惨慄，我讵自云乐。","伊人婴疾恙，所对唯苦药。","寂寞行稍稀，清羸餐自薄。","幽斋外浮事，梦寐亦简略。","雪户掩复明，风帘卷还落。","方持数杯酒，勉子同斟酌。"]},{"t":"寄杨茂卿校书","f":"五言古诗","c":["去年别君时，同宿黎阳城。","黄河冻欲合，船入冰罅行。","君为使滑州，我来西入京。","丈夫不泣别，旁人叹无情。","到京就省试，落籍先有名。","惭辱乡荐书，忽欲自受刑。","还家岂无路，羞为路人轻。","决心住城中，百败望一成。","腐草众所弃，犹能化为萤。","岂我愚暗身，终久不发明。","所悲道路长，亲爱难合并。","还如舟与车，奔走各异程。","耳目甚短狭，背面若聋盲。","安得学白日，远见君仪形。"]},{"t":"寄狄拾遗时为魏州从事","f":"五言古诗","c":["少在兵马间，长还系戎职。","鸡飞不得远，岂要生羽翼。","三年城中游，与君最相识。","应知我中肠，不苟念衣食。","主人树勋名，欲灭天下贼。","愚虽乏智谋，愿陈一夫力。","人生须气健，饥冻缚不得。","睡当一席宽，觉乃千里窄。","古人不惧死，所惧死无益。","至交不可合，一合难离坼。","君尝相劝勉，苦语毒胸臆。","百年心知同，谁限河南北。"]},{"t":"寄陕府内兄郭囧端公","f":"五言古诗","c":["蹇钝无大计，酷嗜进士名。","为文性不高，三年住西京。","相府执文柄，念其心专精。","薄艺不退辱，特列为门生。","事出自非意，喜常少于惊。","春榜四散飞，数日遍八纮。","眼始见花发，耳得闻鸟鸣。","免同去年春，兀兀聋与盲。","家寄河朔间，道路出陕城。","暌违逾十年，一会豁素诚。","同游山水穷，狂饮飞大觥。","起坐不相离，有若亲弟兄。","中外无亲疏，所算在其情。","久客贵优饶，一醉旧疾平。","家远归思切，风雨甚亦行。","到兹恋仁贤，淹滞一月程。","新诗忽见示，气逸言纵横。","缠绵意千里，骚雅文发明。","永昼吟不休，咽喉乾无声。","羁贫重金玉，今日金玉轻。"]},{"t":"寄贾岛浪仙","f":"五言古诗","c":["悄悄掩门扉，穷窘自维絷。","世途已昧履，生计复乖缉。","疏我非常性，端峭尔孤立。","往还纵云久，贫蹇岂自习。","所居率荒野，宁似在京邑。","院落夕弥空，虫声雁相及。","衣巾半僧施，蔬药常自拾。","凛凛寝席单，翳翳灶烟湿。","颓篱里人度，败壁邻灯入。","晓思已暂舒，暮愁还更集。","风凄林叶萎，苔糁行径涩。","海峤誓同归，橡栗充朝给。"]},{"t":"得舍弟书","f":"五言律诗","c":["亲戚多离散，三年独在城。","贫居深稳卧，晚学爱闲名。","小弟有书至，异乡无地行。","悲欢相并起，何处说心情。"]},{"t":"喜胡遇至","f":"五言古诗","c":["穷居稀出入，门户满尘埃。","病少闲人问，贫唯密友来。","茅斋从埽破，药酒遣生开。","多事经时别，还愁不宿回。","就林烧嫩笋，绕树拣香梅。","相对题新什，迟成举罚杯。"]},{"t":"游终南山","f":"五言律诗","c":["策杖度溪桥，云深步数劳。","青猿吟岭际，白鹤坐松梢。","天外浮烟远，山根野水交。","自缘名利系，好此结蓬茆。"]},{"t":"答韩湘","f":"五言古诗","c":["疏散无世用，为文乏天格。","把笔日不休，忽忽有所得。","所得良自慰，不求他人识。","子独访我来，致诗过相饰。","君子无浮言，此诗应亦直。","但虑忧我深，鉴亦随之惑。","子在名场中，屡战还屡北。","我无数子明，端坐空叹息。","昨闻过春关，名系吏部籍。","三十登高科，前涂浩难测。","诗人多峭冷，如水在胸臆。","岂随寻常人，五藏为酒食。","期来作酬章，危坐吟到夕。","难为间其辞，益贵我纸墨。"]},{"t":"答窦知言","f":"五言古诗","c":["冬日易惨恶，暴风拔山根。","尘沙落黄河，浊波如地翻。","飞鸟皆束翼，居人不开门。","独我赴省期，冒此驰毂辕。","陕城城西边，逢子亦且奔。","所趋事一心，相见如弟昆。","我惨得子舒，我寒得子温。","同行十日程，僮仆性亦敦。","到京人事多，日无闲精魂。","念子珍重我，吐辞发蒙昏。","反复千万意，一百六十言。","格高思清冷，山低济浑浑。","尝闻朋友惠，赠言始为恩。","金玉日消费，好句长存存。","倒篚别收贮，不与俗士论。","每当清夜吟，使我如哀猿。"]},{"t":"街西居三首 其一","f":"五言古诗","c":["受得山野性，住城多事违。","青山在宅南，回首东西稀。","浅浅一井泉，数家同汲之。","独我恶水浊，凿井庭之陲。","自凿还自饮，亦为众所非。","吁嗟世间事，洁身诚难为。"]},{"t":"街西居三首 其二","f":"五言古诗","c":["日出穷巷喜，温然胜重衣。","重衣岂不煖，所煖人不齐。","兀兀复行行，不离阶与墀。"]},{"t":"街西居三首 其三","f":"五言古诗","c":["丈夫非马蹄，安得知路岐。","穷贱飧茹薄，兴与养性宜。","乃知长生术，豪贵难得之。"]},{"t":"感时","f":"五言古诗","c":["忆昔未出身，索寞无精神。","逢人话天命，自贱如埃尘。","君今才出身，飒爽鞍马春。","逢人话天命，自重如千钧。","信涉名利道，举动皆丧真。","君今自世情，何况天下人。"]},{"t":"新居秋夕寄李廓","f":"五言古诗","c":["羁滞多共趣，屡屡同室眠。","稍暇更访诣，宁唯候招延。","愧君备蔬药，识我性所便。","罢吏童仆去，洒扫或自专。","古巷人易息，疏迥自江边。","幸当中秋夕，复此无云天。","月华更漏清，露叶光彩鲜。","四邻亦悄悄，中怀益缠绵。","兹境罕能致，居闲得弥偏。","数杯罢复饮，共想山中年。"]},{"t":"新昌里","f":"五言古诗","c":["旧客常乐坊，井泉浊而咸。","新屋新昌里，井泉清而甘。","僮仆惯苦饮，食美翻憎嫌。","朝朝忍饥行，戚戚如难堪。","中下无正性，所习便淫耽。","一染不可变，甚于茜与蓝。","近贫日益廉，近富日益贪。","以此当自警，慎勿信邪谗。"]},{"t":"酬杨汝士尚书喜人移居","f":"五言律诗","c":["未得沧江外，衰残读药书。","圣朝优上秩，仁里许闲居。","树对枝相接，泉同井不疏。","酬章深自鄙，欲寄复踌蹰。"]},{"t":"题金州西园九首 石庭","f":"五言古诗","c":["布石满山庭，磷磷洁还清。","幽人常履此，月下屐齿鸣。","药草枝叶动，似向山中生。"]},{"t":"题金州西园九首 江榭","f":"五言古诗","c":["亭亭白云榭，下有清江流。","见江不得亲，不如波上鸥。","有榭江可见，无榭无双眸。"]},{"t":"题金州西园九首 芭蕉屏","f":"五言古诗","c":["芭蕉丛丛生，月照参差影。","数叶大如墙，作我门之屏。","稍稍闻见稀，耳目得安静。"]},{"t":"题金州西园九首 松坛","f":"五言古诗","c":["盘盘松上盖，下覆青石坛。","月中零露垂，日出露尚漙。","山翁称绝境，海桥无所观。"]},{"t":"题金州西园九首 垣竹","f":"五言古诗","c":["种竹爱庭际，亦以资玩赏。","穷秋雨萧条，但见墙垣长。","宣尼高数仞，固应非土壤。"]},{"t":"题金州西园九首 草阁","f":"五言古诗","c":["编草覆柏椽，轩扉皆竹织。","閤成似僧居，学僧居未得。","有时公府劳，还复来此息。"]},{"t":"题金州西园九首 药堂","f":"五言古诗","c":["僮仆不到阈，双扉常自关。","四壁画远水，堂前耸秋山。","时闻有仙鼠，窃药檐隙间。"]},{"t":"题金州西园九首 莓苔","f":"五言古诗","c":["茅堂阶岂高，数寸是苔藓。","只恐秋雨中，窗户亦不溅。","眼前无此物，我情何由遣。"]},{"t":"题金州西园九首 葼径","f":"五言古诗","c":["药院径亦高，往来踏葼影。","方当繁暑日，草屩微微冷。","爱此不能行，折薪坐煎茗。"]},{"t":"题崔驸马宅","f":"七言律诗","c":["心在林泉身在城，凤凰楼下得闲名。","洞中见凿寻仙路，月里犹烧煮药铛。","数树异花皆敕赐，并竿修竹自天生。","诗人多说离君宅，不得青苔地上行。"]},{"t":"赠卢沙弥小师","f":"五言古诗","c":["怕见世间事，削头披佛衣。","年小未受戒，会解如老师。","天与出家肠，一食斋不饥。","麻履踏雪路，与马不肯骑。","嫌我身腥膻，似我见戎夷。","彼此见会异，对面成别离。","我师文宣王，立教垂书诗。","但全仁义心，自然便慈悲。","两教大体同，无处辨是非。","莫以衣服别，到头不相知。"]},{"t":"赠终南山傅山人","f":"五言古诗","c":["七十未成事，终南苍鬓翁。","老来诗兴苦，贫去酒肠空。","蟠蛰身仍病，鹏抟力未通。","已无烧药本，唯有著书功。","白马时何晚，青龙岁欲终。","生涯枯叶下，家口乱云中。","潭静鱼惊水，天晴鹤唳风。","悲君还姓傅，独不梦高宗。"]},{"t":"句","f":"古风","c":["天遥来雁小，江阔去帆孤。","南陌游人回首去，东林道者杖藜归。","萄藤洞庭头，引叶漾盈摇。","皎洁钩高挂，玲珑影落寮。","阴烟压幽屋，濛密梦冥苗。","清秋青且翠，冬到冻都凋。"]}]};